(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0022.js"] = [{"id":"poem-90a8db87a78bce5937d40499","title":"三衢道中","author":"曾几","dynasty":"宋","verses":["梅子黄时日日晴，小溪泛尽却山行。","绿阴不减来时路，添得黄鹂四五声。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-三衢道中","tags":[]},{"id":"poem-90adab9b5dd10545337f4638","title":"浣溪沙·小阁重帘有燕过","author":"晏殊","dynasty":"宋","verses":["小阁重帘有燕过。","晚花红片落庭莎。","曲阑干影入凉波。","一霎好风生翠幕，几回疏雨滴圆荷。","酒醒人散得愁多。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-438","tags":[]},{"id":"poem-90b126b4bce072e836ece375","title":"江上书怀","author":"崔峒","dynasty":"唐","verses":["骨肉天涯别，江山日落时。","泪流襟上血，发变镜中丝。","胡越书难到，存亡梦岂知。","登高回首罢，形影自相随。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b8cb002c-be55-4c7b-8725-3983ebec476f","tags":[]},{"id":"poem-90b12749dc02c1113b0e7548","title":"大迓鼓","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(且)你结交恩义深，不知因甚反面忘恩？我劝你不从听，霸王空有重瞳目，官人，有眼何曾识好人！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1905","tags":[]},{"id":"poem-90b259c0672191c658c7e57c","title":"送严员外","author":"李嘉祐","dynasty":"唐","verses":["春风倚櫂阖闾城，水国春寒阴复晴。","细雨湿衣看不见，闲花落地听无声。","日斜江上孤帆影，草绿湖南万里情。","君去若逢相识问，青袍今已误儒生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1a3d6317-14e6-4974-85bf-696d58458a5e","tags":["写雨","送别","怀才不遇","雨"]},{"id":"poem-90b5182062b4ba2796b736be","title":"棠棣","author":"佚名","dynasty":"先秦","verses":["棠棣之华，鄂不韡韡。凡今之人，莫如兄弟。","死丧之威，兄弟孔怀。原隰裒矣，兄弟求矣。","脊令在原，兄弟急难。每有良朋，况也永叹。","兄弟阋于墙，外御其务。每有良朋，烝也无戎。","丧乱既平，既安且宁。虽有兄弟，不如友生？","傧尔笾豆，饮酒之饫。兄弟既具，和乐且孺。","妻子好合，如鼓瑟琴。兄弟既翕，和乐且湛。","宜尔室家，乐尔妻帑。是究是图，亶其然乎？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-163","tags":[]},{"id":"poem-90b83420b72dce42df18eda0","title":"谢新恩·庭空客散人归后","author":"李煜","dynasty":"五代","verses":["庭空客散人归后，画堂半掩珠帘。","林风淅淅夜厌厌。","小楼新月，回首自纤纤。","春光镇在人空老，新愁往恨何穷！","金窗力困起还慵。","一声羌笛，惊起醉怡容。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-32","tags":[]},{"id":"poem-90c48bde38197c0d1c3c4209","title":"题裴晋公华岳庙题名","author":"司空图","dynasty":"唐","verses":["岳前大队赴淮西，从此中原息鼓鼙。","石阙莫教苔藓上，分明认取晋公题。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6faaea56-dbe9-459c-8592-d6cb02069bf2","tags":["华山"]},{"id":"poem-90c910ec578860a5bf7e4823","title":"送察院李侍御使庐陵因寄孟员外","author":"徐铉","dynasty":"宋","verses":["绣衣乘驿急如星，山水何妨寄野情。","肯向九仙台下歇，闲听孟叟醉吟声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e92189cc-d4c9-4e4d-ac90-99b3dd731b29","tags":[]},{"id":"poem-90cfaa9d50704003cd01fff8","title":"筹笔驿","author":"李商隐","dynasty":"唐","verses":["猿鸟犹疑畏简书，风云常为护储胥。","徒令上将挥神笔，终见降王走传车。","管乐有才终不忝，关张无命欲何如。","他年锦里经祠庙，梁父吟成恨有余。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-131c9f87-273f-4684-9b67-bd7b58ad4008","tags":["唐诗三百首","隋・唐・五代","七言律诗","典故","写人","咏史怀古"]},{"id":"poem-90d9d13e1ec86592cab0aa6c","title":"彭尉焚巢二首  其二","author":"陈造","dynasty":"宋","verses":["迺翁五车读，弓剑初一命。","九十归田园，颜丹眼如镜。","客来不告倦，笔落有余劲。","霜严草花落，松柏独也正。","吾怜盼与札，徐阅襄昭定。","济美竟寂寞，陈编漫辉映。","翁家戏彩郎，足继贤业盛。","雄词逼王杨，奥学窥韩孟。","援今校古昔，两翁犹此病。","今段天试君，处此要以静。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e309380c-7b18-4dad-bad2-d86744d5891d","tags":[]},{"id":"poem-90daa92162a3b069bdc11886","title":"东方未明","author":"佚名","dynasty":"先秦","verses":["东方未明，颠倒衣裳。颠之倒之，自公召之。","东方未晞，颠倒裳衣。倒之颠之，自公令之。","折柳樊圃，狂夫瞿瞿。不能辰夜，不夙则莫。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-99","tags":[]},{"id":"poem-90dcd4aef2709cf62777f591","title":"鲤鱼","author":"项斯","dynasty":"唐","verses":["似龙鳞又足，只是欠登门。","月里腮犹湿，泥中目未昏。","乞锄防蚁穴，望水写金盆。","他日能为雨，公田报此恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-925eb6e7-50a8-4683-8f76-155d993df2a2","tags":[]},{"id":"poem-90deab9f10004766a2379504","title":"荷叶杯·夜久歌声怨咽","author":"顾敻","dynasty":"五代","verses":["夜久歌声怨咽，残月。","菊冷露微微，看看湿透缕金衣。","归么归，归么归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-25","tags":[]},{"id":"poem-90e64770679c93861abc4d93","title":"昔昔盐二十首 蘼芜叶复齐","author":"赵嘏","dynasty":"唐","verses":["提筐红叶下，度日采蘼芜。","掬翠香盈袖，看花忆故夫。","叶齐谁复见，风暖恨偏孤。","一被春光累，容颜与昔殊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-984a653c-4bf1-4110-8fda-66ddccb1d8f6","tags":[]},{"id":"poem-90ec1f7043e354805dc88b97","title":"同阎伯均宿道士观有述","author":"包何","dynasty":"唐","verses":["南国佳人去不回，洛阳才子更须媒。","绮琴白雪无心弄，罗幌清风到晓开。","冉冉修篁依户牖，迢迢列宿映楼台。","纵令奔月成仙去，且作行云入梦来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-969d645c-9a62-4480-97a2-10621a949360","tags":[]},{"id":"poem-90eda71c0f1cc9d7dd89251a","title":"渔家傲·杨柳风前香百步","author":"晏殊","dynasty":"宋","verses":["杨柳风前香百步。","盘心碎点真珠露。","疑是水仙开洞府。","妆景趣。","红幢绿盖朝天路。","小鸭飞来稠闹处。","三三两两能言语。","饮散短亭人欲去。","留不住。","黄昏更下萧萧雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-512","tags":[]},{"id":"poem-90f476c565c62edc316be733","title":"句 四","author":"延寿","dynasty":"唐","verses":["草浓春径狭，树密晚窗阴。","（均见明刻本《吟窗杂录》卷三十二《古今诗僧》。","）（按：延寿卒于开宝八年，时吴越虽已奉宋为正朔，用其年号，而仍维持独立。","吴越纳土，为延寿卒后三年之事。","诸书或以延寿为宋人，实未谛。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-9488704d-1021-4964-822e-863801c0f284","tags":[]},{"id":"poem-90f69074146847b8b83b290f","title":"春秋战国门 齐桓公","author":"周昙","dynasty":"唐","verses":["三往何劳万乘君，五来方见一微臣。","微臣傲爵能轻主，霸主如何敢傲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dc4c506e-541c-4bd5-9610-1a6c06b089f9","tags":[]},{"id":"poem-910191dfb783a6a6db539af8","title":"赠同游","author":"杨凝","dynasty":"唐","verses":["此囗风雨后，已觉减年华。","若待皆无事，应难更有花。","管弦临夜急，榆柳向江斜。","且莫看归路，同须醉酒家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-29f41c00-2f43-47cc-99dc-b4749beef2fc","tags":[]},{"id":"poem-910a5f7b7d4b2e8bd382ce6b","title":"苦雨","author":"陈造","dynasty":"宋","verses":["有足不下楼，有耳祇听雨。","一日不可耐，忽忽弥旬所。","轩盖断还往，尸居成独语。","日色似见慰，云气复如许。","西湖梅柳月，裘马趁箫鼓。","细追他日梦，一笑念缚虎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-dac2c551-5c38-4307-9647-aade0bc2f34c","tags":["西湖"]},{"id":"poem-910ff80e9af95987d0a93a8b","title":"旧国里","author":"卿云","dynasty":"唐","verses":["旧居梨岭下，风景近炎方。","地暖生春早，家贫觉岁长。","石房云过湿，杉径雨余香。","日夕竟无事，诗书聊自强。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e55f3f89-6ae3-400c-8f90-5288a425c01e","tags":[]},{"id":"poem-9111a23a8730473e4842c4c1","title":"偶作因怀大同道友","author":"贯休","dynasty":"唐","verses":["蛮木叶不落，微吟漳水滨。","二毛空有雪，万事不如人。","壍水平芳草，山花落净巾。","天童好真伴，何日更相亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b27ab0cb-2e3e-4f65-aef8-7f8d226b5492","tags":[]},{"id":"poem-9116b83c855f796ba0b86298","title":"大水","author":"薛逢","dynasty":"唐","verses":["暴雨逐惊雷，从风忽骤来。","浪驱三岛至，江拆二仪开。","势恐圆枢折，声疑厚轴摧。","冥心问元化，天眼几时回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c717d4bc-574c-4c04-a9a0-5292fad95c82","tags":[]},{"id":"poem-9127024e94cdf7493818c9bf","title":"从军有苦乐行","author":"李益","dynasty":"唐","verses":["劳者且莫歌，我欲送君觞。","从军有苦乐，此曲乐未央。","仆居在陇上，陇水断人肠。","东过秦宫路，宫路入咸阳。","时逢汉帝出，谏猎至长杨。","讵驰游侠窟，非结少年场。","一旦承嘉惠，轻身重恩光。","秉笔参帷帟，从军至朔方。","边地多阴风，草木自凄凉。","断绝海云去，出没胡沙长。","参差引雁翼，隐辚腾军装。","劒文夜如水，马汗冻成霜。","侠气五都少，矜功六郡良。","山河起目前，睚眦死路傍。","北逐驱獯虏，西临复旧疆。","昔还赋余资，今出乃赢粮。","一矢弢夏服，我弓不再张。","寄语丈夫雄，苦乐身自当。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-515db1b8-0e77-479d-b284-337960ed594c","tags":[]},{"id":"poem-912c3d9fa8f16fa9f94d8e32","title":"闻查建州陷贼寄钟郎中","author":"徐铉","dynasty":"宋","verses":["闻道将军轻壮图，螺江城下委犀渠。","旌旗零落沉荒服，簪履萧条返故居。","皓首应全苏武节，故人谁得李陵书。","自怜放逐无长策，空使卢谌泪满裾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-15064aa1-9a3f-4217-89c7-3abf0c4b2d16","tags":[]},{"id":"poem-912e6ded45824bcc2491ffb7","title":"和公度","author":"刘跂","dynasty":"宋","verses":["多情佳客送春来，雉尾猫头次第栽。","从此庭前共苍翠，夭桃繁杏不须开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-13cdfc9e-ec9a-4d52-815b-3a223002c654","tags":[]},{"id":"poem-9138d843e53874e23f9bb979","title":"容南初食荔枝二首  其二","author":"李纲","dynasty":"宋","verses":["买地城南种荔枝，毎留核付守园儿。","但祈四海兵戈息，会见开花著子时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3802ad94-81a5-4430-a30d-b43c0405a1ca","tags":[]},{"id":"poem-9147f3f6ae9bc8d8c9a58af2","title":"横吹曲辞 出关","author":"魏征","dynasty":"唐","verses":["中原还逐鹿，投笔事戎轩。","纵横计不就，慷慨志犹存。","策杖谒天子，驱马出关门。","请缨羁南越，凭轼下东藩。","郁纡陟高岫，出没望平原。","古木吟寒鸟，空山啼夜猨。","既伤千里目，还惊九折魂。","岂不惮艰险，深怀国士恩。","季布无二诺，侯嬴重一言。","人生感意气，功名谁复论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ed0d4f1c-f300-48b1-8139-706fb3a1aa2c","tags":[]},{"id":"poem-914d7407405e758c65d593d4","title":"偈颂（幷序○序为南岳齐己撰） 八十一","author":"居遁","dynasty":"唐","verses":["破布裹闻身，无言可示人。","居山山得乐，住郭郭还欣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-99ea3bb5-446e-4f73-b053-bb7fc2326e90","tags":["衡山"]},{"id":"poem-914e222acf452f4c0b89ffdf","title":"宿桐庐江寄广陵旧游","author":"孟浩然","dynasty":"唐","verses":["山暝闻猿愁，沧江急夜流。","风鸣两岸叶，月照一孤舟。","建德非吾土，维扬忆旧游。","还将两行泪，遥寄海西头。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b1dad78c-4dd8-4b99-b37b-741ed761f26a","tags":["唐诗三百首","描写水","五言律诗","怀人","写水"]},{"id":"poem-915b72b594978f402f7a0fe9","title":"清明","author":"高菊卿","dynasty":"宋","verses":["南北山头多墓田，清明祭扫各纷然。","纸灰飞作白蝴蝶，泪血染成红杜鹃。","日落狐狸眠冢上，夜归儿女笑灯前。","人生有酒须当醉，一滴何曾到九泉。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-清明","tags":[]},{"id":"poem-9173f7faf864024083ea80ce","title":"白马峰","author":"延寿","dynasty":"唐","verses":["湖外层峰泻危楼，天际阴阴长寒木。","南北行人望莫穷，秋云一片横幽谷。","（见南宋张淏《宝庆续会稽志》卷四「姜山」条。","《乾隆绍兴府志》卷四、《光绪余姚县志》卷二亦载此五首诗，字句颇有异同。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-70b94b19-79d5-40e5-bd8f-dae5e93cff40","tags":[]},{"id":"poem-9176aea770296b330a6be8ec","title":"荷叶杯·弱柳好花尽坼","author":"顾敻","dynasty":"五代","verses":["弱柳好花尽坼，晴陌。","陌上少年郎，满身兰麝扑人香。","狂么狂，狂么狂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-23","tags":[]},{"id":"poem-917c37fe492ca7f08a54f471","title":"临安长官号两山","author":"释居简","dynasty":"宋","verses":["小筑难谋似燕营，卷帘容燕贺新成。","绿抽万玉医人俗，青出双螺闯户明。","家与宦贫宁免仕，猨教鹤伴不须惊。","紫荆花下庭萱老，浊酒狂歌燕弟兄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-58e71b09-95a8-4d96-9645-6a36f7ca25b5","tags":[]},{"id":"poem-918422bc2e7d9e0c09ea099a","title":"题柏屿水瘦屏","author":"释居简","dynasty":"宋","verses":["此妙伊谁得，能名惜不闻。","痕收新涨水，瘦宿暝归云。","烟霭疑无墨，凫鹥不乱群。","可堪擅毫素，幽讨盍平分。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-35995665-a3e9-44b2-b41a-f105248e7c6a","tags":[]},{"id":"poem-91aa85c29aa8ddd68e07e718","title":"新水令","author":"施惠《幽闺记》","dynasty":"元","verses":["(老旦)凄凉逆旅人千早，(旦)这萦牵怎生成寐？(小旦)万苦横心里。","(合)睡不着，是愁都做枕边泪。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3024","tags":[]},{"id":"poem-91ad8e91274333833af1e221","title":"送卢缄归扬州","author":"薛逢","dynasty":"唐","verses":["曾向雷塘寄掩扉，荀家灯火有余辉。","关河日暮望空极，杨柳渡头人独归。","隋苑荒台风褭褭，灞陵残雨梦依依。","今年春色还相悮，为我江边谢钓矶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5001bf44-e94e-4a2b-a2b9-cbc65005f72a","tags":[]},{"id":"poem-91c25c28f0354da2ef78df7c","title":"薄命女·天欲晓","author":"和凝","dynasty":"五代","verses":["天欲晓，宫漏穿花声缭绕。","窗里星光少，冷霞寒侵帐额，残月光沉树杪。","梦断锦帷空悄悄，强起愁眉小。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-22","tags":[]},{"id":"poem-91c526a4bdd02baabccdcb21","title":"游南雁荡","author":"薛正明","dynasty":"唐","verses":["遐僻山深自晦明，峨峨千态画难成。","半空高挂龙湫瀑，万仞宏开金石城。","日射岚光轻锁黛，泉飞竹径细鸣筝。","隐山无路停骖问，拂拂清风两腋生。","（见周喟《南雁荡山志》卷七引郑思恭《崇祯南雁山志》。","）（按：薛正明逸诗及小传，承张靖龙同志录示。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-994066a9-b4b1-43d8-8249-85bbf2602764","tags":[]},{"id":"poem-91ca217fd392e9cfb5e8073b","title":"春水曲","author":"张籍","dynasty":"唐","verses":["鸭鸭，觜唼唼。","青蒲生，春水狭。","荡漾木兰船，中有双少年。","少年醉，鸭不起。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f9f520a9-13e6-4379-b6fd-f86904c219d6","tags":[]},{"id":"poem-91cb7c1c52e28cb16b093bb6","title":"送表姪达师归鄱阳","author":"徐铉","dynasty":"宋","verses":["故乡禾黍世亲稀，中表相寻只有师。","惆怅离怀向何许，鄱阳湖上叶飞时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-49ea39e6-25fc-4391-ae57-a4f7e478212d","tags":[]},{"id":"poem-91d62b302ca7679f466a520e","title":"献主司","author":"孟宾于","dynasty":"宋","verses":["那堪雨后更闻蝉，溪隔重湖路七千。","忆昔故园杨柳岸，全家送上渡头船。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-80f3fbc3-77c6-42a8-86aa-bea8cfc9380a","tags":[]},{"id":"poem-91dda3e42271ebda543928a0","title":"调笑・调笑令·心记","author":"晁补之","dynasty":"宋","verses":["心记。","好心事。","玉刻容颜眉刷翠。","杜郎生得真男子。","况是东家妖丽。","眉尖春恨难凭寄。","笑作空中唐字。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-284","tags":[]},{"id":"poem-91e4840355a5f00536868587","title":"喜英公大师挂锡太华","author":"陈抟","dynasty":"宋","verses":["暗喜莲峰作近隣，拨开云雾见师频。","有时问个艰难字，便沐周旋说与人。","唐李监应留后迹，汉蔡邕想是前身。","堪嗟继踵无徒弟，笔法收藏在渭滨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6c13aea3-3c99-4a20-9a15-7ead109fb3be","tags":[]},{"id":"poem-91e728caee3a7d8d67ab1e66","title":"病起四诗 三息念","author":"陈造","dynasty":"宋","verses":["禄位据极品，勋业垂不磨。","出从白马肥，家有黄金多。","世间贵富者，才德乃莫过。","骨相审自知，瓮盎哀骀他。","一昔读书史，志空慕丘轲。","矻矻章句乐，所趣不及他。","日月倏迁谢，如此定命何。","知己初不无，腰金鸣玉珂。","一旦逝水去，匪斧嗟不柯。","揆材既樗栎，揣分合涧薖。","旌翻火驰余，但有双鬓皤。","迨今要勇往，灌园仍养疴。","石女自无儿，古井那解波。","西湖佳风烟，久矣办一蓑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8cda40fe-7e01-41a8-9994-b930e3090d9c","tags":["西湖"]},{"id":"poem-91ed8567d876f0b4ce8c6f96","title":"临江仙·峭碧参差十二峰","author":"牛希济","dynasty":"五代","verses":["峭碧参差十二峰，冷烟寒树重重。","瑶姬宫殿是仙踪，金炉珠帐，香霭昼偏浓。","一自楚王惊梦断，人间无路相逢。","至今云雨带愁容，月斜江上，征棹动晨钟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-33","tags":[]},{"id":"poem-91fc08bd6e3b5b8725785664","title":"梁台古愁","author":"李贺","dynasty":"唐","verses":["梁王台沼空中立，天河之水夜飞入。","台前鬬玉作蛟龙，绿粉扫天愁露湿。","撞钟饮酒行射天，金虎蹙裘喷血斑。","朝朝暮暮愁海翻，长绳系日乐当年。","芙蓉凝红得秋色，兰脸别春啼脉脉。","芦洲客雁报春来，寥落野篁秋漫白。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ff19d74e-bc9a-48e9-9f9b-ab9722df50a9","tags":[]},{"id":"poem-920577abc0adffc3a19c7c5a","title":"宫词五首 二","author":"顾况","dynasty":"唐","verses":["玉楼天半起笙歌，风送宫嫔笑语和。","月殿影开闻夜漏，水精帘卷近银河。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-aa9f9e4d-aa34-496e-89cf-cfef61efa89d","tags":["唐诗三百首"]},{"id":"poem-9209048e9c34dc33b7c15ea5","title":"浣溪沙·清晓妆成寒食天","author":"韦庄","dynasty":"五代","verses":["清晓妆成寒食天，柳球斜袅间花钿，卷帘直出画堂前。","指点牡丹初绽朵，日高犹自凭朱栏，含颦不语恨春残。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-28","tags":[]},{"id":"poem-920d05c08ed80a76f0c29b18","title":"尾声","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(众)刘朗误入桃源里，羡满门恩情乐意，愿百岁夫妻直到底。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8842","tags":[]},{"id":"poem-920f76c0b9db10c834c3b9d4","title":"送龙门令刘沧","author":"张乔","dynasty":"唐","verses":["去宰龙门县，应思变化年。","还将鲁儒政，又与晋人传。","峭壁开中古，长河落半天。","几乡因劝勉，耕稼满云烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b78f17a5-1503-40cd-800b-a8d64d6ca044","tags":[]},{"id":"poem-92110f1230ae9873daa85443","title":"新桃行","author":"张籍","dynasty":"唐","verses":["桃生叶婆娑，枝叶四向多。","高未出墙颠，蒿苋相凌摩。","植之三年余，今年初试花。","秋来已成实，其阴良已嘉。","青蝉不来鸣，安得迅羽过。","常恶牵丝虫，蒙幂成网罗。","顾托戏儿童，勿折吾柔柯。","明年结其实，磊磊充汝家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-029ff16c-6562-4d06-95d9-765045b30c69","tags":[]},{"id":"poem-92191406324a5c431ad982c9","title":"谣俗词","author":"曹操","dynasty":"汉","verses":["瓮中无斗储，发箧无尺缯。","友来从我贷，不知所以应。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-24","tags":[]},{"id":"poem-922964ff5ac9b7d99e9c2bec","title":"王叔武示忠州张使君德远近诗次韵三首  其二","author":"曾协","dynasty":"宋","verses":["妙理居言外，高怀见酒边。","无心千里奉，有意一灯传。","柏树谁能指，虚空莫问年。","炉香聊闭合，何处觅心田。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-0bc6e783-3172-45ff-9c22-cd5226e55469","tags":[]},{"id":"poem-922bbfe219371bc244b5470a","title":"寄题临江玉实斋司户百花洲","author":"宋伯仁","dynasty":"宋","verses":["锦囊诗里识花洲，何日清江得醉游。","百亩故园重饾饤，四贤遗像愈风流。","香浮红树春应早，雪压寒梅月想留。","我有烟波鱼具了，一丝风底愿维舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-3ccd9fc6-f28f-4453-b32b-e6039dacc203","tags":[]},{"id":"poem-9232c3b76e3748d4508892a4","title":"河传·江畔","author":"温庭筠","dynasty":"唐","verses":["江畔，相唤。","晓妆鲜，仙景个女采莲。","请君莫向那岸边，少年，好花新满船。","红袖摇曳逐风暖，垂玉腕，肠向柳丝断。","浦南归，浦北归，莫知，晚来人已稀。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-8","tags":[]},{"id":"poem-9233032217ec2c61b8991dde","title":"郊庙歌辞 祀九宫贵神乐章 寿和","author":"不详","dynasty":"唐","verses":["时文哲后，肃事严禋。","馨我明德，享于贵神。","大庖载盈，旨酒斯醇。","精意所属，期于利人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d9e99408-1966-4113-a6c0-10216d7de918","tags":[]},{"id":"poem-9233f718ea0f47cac95c974e","title":"击鼓","author":"佚名","dynasty":"先秦","verses":["击鼓其镗，踊跃用兵。土国城漕，我独南行。","从孙子仲，平陈与宋。不我以归，忧心有忡。","爰居爰处？爰丧其马？于以求之？于林之下。","死生契阔，与子成说。执子之手，与子偕老。","于嗟阔兮，不我活兮。于嗟洵兮，不我信兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-30","tags":[]},{"id":"poem-9235d447127123296b9b713e","title":"湖山即景次尹绿波","author":"王镃","dynasty":"宋","verses":["湖山掩映雁潭秋，今古诗人说胜游。","绿柳影分骑马路，赤枫叶落钓鱼舟。","前坡风送归樵笛，别墅云藏卖酒楼。","长记寻梅冰雪里，毡靴驼帽鹔鹴裘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4444673d-966b-4b7d-8e03-9dd6ee91cff5","tags":[]},{"id":"poem-9242150dc446342a4aa74e3f","title":"游春引三首 二","author":"张碧","dynasty":"唐","verses":["五陵年少轻薄客，蛮锦花多春袖窄。","酌桂鸣金玩物华，星蹄绣毂填香陌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8b006226-237f-4f13-b01f-5f8cee04c2bb","tags":[]},{"id":"poem-9245865df97ffdfb4613f14b","title":"壮观二首  其二","author":"米芾","dynasty":"宋","verses":["梦寐中间得鹿时，孔轩如在定能知。","江山胜处频倾酒，我是当年谢客儿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b62dcf3c-0c23-4ff1-a996-e8ee413839ef","tags":[]},{"id":"poem-924b132bf7939e0f717093a4","title":"胜如花","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["辞亲去，别泪零，岂料登山蓦领。","只因人递简传书，教娘离乡背井，未知道何日欢庆？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8230","tags":[]},{"id":"poem-925a29d7ee2f24b68a4c8aec","title":"偶作二首 二","author":"贯休","dynasty":"唐","verses":["门前数枝路，路路车马鸣。","名埃与利尘，千里万里行。","只见青山高，岂见青山平。","朱门势峨峨，冠盖何光明。","黄鸟在花里，青蝉夺其声。","尔生非金玉，岂常贵复贞。","寄言之子心，可以归无形。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-46bc2d31-92f6-4e9b-a69e-df3ce6139ac0","tags":[]},{"id":"poem-925eb5c71f71f9c568f25c78","title":"大唐圣功诗","author":"张祜","dynasty":"唐","verses":["祜闻昔隋末。","炀帝厄围兵。","太宗初应募，杖劎起边征。","扬师列虚旗，首激将军诚。","神略在一断，解围当未萌。","高祖守河东，权力已兼幷。","猖狂蚁结徒，举踵乃击平。","隋德日已衰，俯折士尊名。","群才{牙丿=丶}相枤，诺以义为盟。","屯军起边州，李密驰传迎。","杨眉爱姿度，失口真王英。","由是太河南，千里响应声。","降王与拘窦，亲待入宫城。","乃命臣萧瑀，府库掌虚盈。","次命臣玄龄，图书收付卿。","开牢释姧枉，各更重从轻。","回戈略伪主，太庙告明明。","殊功苟未已，徽号为重旌。","文物一以兴，贤良俱间生。","声诗日盈听，智论益纵横。","何意萧墙内，阴谋中构倾。","直词虽可进，王法讵该情。","甲子上即位，南郊赦宪灜。","八蛮与四夷，朝贡路交争，三月后亲蚕，癸亥上亲耕。","侍臣虞南等，碑以纪功成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-08978ad6-2097-4f42-a579-fc71623735b2","tags":[]},{"id":"poem-925ed722ea6e44de8ba33deb","title":"姑熟杂咏 望夫山","author":"李赤","dynasty":"唐","verses":["颙望临碧空，怨情感离别。","芳草不知愁，岩花但争发。","云山万重隔，音信千里绝。","春去秋复来，相思几时歇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ed347645-de13-496a-9078-cea6912d3c1c","tags":[]},{"id":"poem-925ee4513abf3d5f6a20921e","title":"玉华宫","author":"杜甫","dynasty":"唐","verses":["溪回松风长，苍鼠窜古瓦。","不知何王殿，遗构绝壁下。","阴房鬼火青，坏道哀湍泻。","万籁真笙竽，秋色正萧洒。","美人为黄土，况乃粉黛假。","当时侍金舆，故物独石马。","忧来藉草坐，浩歌泪盈把。","冉冉征途间，谁是长年者。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cb457f4a-a49c-46cc-becf-d4419d617b79","tags":[]},{"id":"poem-925f8c031932432b030fb01e","title":"送独孤拾遗先辈先赴上都","author":"李嘉祐","dynasty":"唐","verses":["行春日已晓，桂檝逐寒烟。","转曲遥峰出，看涛极浦连。","入京当献赋，封事更闻天。","日日趋黄阁，应忘云海边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-71435a7a-6541-45dd-a0f3-de97ca80c620","tags":[]},{"id":"poem-925fcf41dae8f44c8b01fdc2","title":"富郑公画像赞","author":"李纲","dynasty":"宋","verses":["天下达德，惟仁智勇。","合之成体，散之致用。","岩岩富公，备此三德。","直道不回，以相王国。","其智伊何，见于使虏。","敷陈利害，以悟其主。","欢盟至今，莫敢予侮。","其仁伊何，见于救灾。","饥民如云，襁负以偕。","法简惠周，垂训将来。","何以行兹，断以勇克。","众人所惧，公独不惑。","夺虏之气，厉色折之。","赈民之饥，诚意活之。","我生后公，今觌厥象。","丹青载传，朝夕是仰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d7b080dd-a463-4cc8-a648-2f0ec097fbea","tags":[]},{"id":"poem-9269bb7f7986318cae485f4d","title":"咏史诗 荆山","author":"胡曾","dynasty":"唐","verses":["抱玉岩前桂叶稠，碧谿寒水至今流。","空山落日猨声呌，疑是荆人哭未休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-7dd73032-2ef8-48c8-93e8-8b3326a017cc","tags":[]},{"id":"poem-92752379a5ef3543c28f6116","title":"忆皎然上人","author":"李端","dynasty":"唐","verses":["未得从师去，人间万事劳。","云门不可见，山木已应高。","向日开柴户，惊秋问敝袍。","何由宿峰顶，窗里望波涛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a5ba3afd-a08c-49e8-a13e-9c90d1d88428","tags":[]},{"id":"poem-927a05952724d75be18a50f9","title":"所居即事六首（原注：丹阳闲居寄郑明府如范上人。） 其六","author":"张祜","dynasty":"唐","verses":["晨起常掻两鬓丝，小亭深坐一洿池。","墙头鸜鹆隈花叶，水面蜻蜓寄草枝。","赖得木奴些子力，生憎鱼婢苦顽痴。","扁舟远棹寻春处，竹榼新醪喜自随。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-78083627-3f1d-4dfb-9853-9aaa0ce0c889","tags":[]},{"id":"poem-9284e0bcb01c2e063b781e0d","title":"渔家傲·乞巧楼头云幔卷","author":"欧阳修","dynasty":"宋","verses":["乞巧楼头云幔卷。","浮花催洗严妆面。","花上蛛丝寻得遍。","颦笑浅。","双眸望月牵红线。","奕奕天河光不断。","有人正在长生殿。","暗付金钗清夜半。","千秋愿。","年年此会长相见。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-660","tags":[]},{"id":"poem-9286a19a1ba1427ce3e99b57","title":"慈恩寺怀旧","author":"李端","dynasty":"唐","verses":["去者不可忆，旧游相见时。","凌霄徒更发，非是看花期。","倚玉交文友，登龙年月久。","东阁许联床，西郊亦携手。","彼苍何暖昧，薄劣翻居后。","重入远师谿，谁尝陶令酒。","伊昔会禅宫，容辉在眼中。","篮舆来问道，玉柄解谈空。","孔席亡颜子，僧堂失谢公。","遗文一书壁，新竹再移丛。","始聚终成散，朝欢暮不同。","春霞方照日，夜烛忽迎风。","蚁鬬声犹在，鸮灾道已穷。","问天应默默，归宅太匆匆。","凄其履还路，莽苍云林暮。","九陌似无人，五陵空有雾。","缅怀山阳笛，永恨平原赋。","错莫过门栏，分明识行路。","上智本全真，郄公况重臣。","唯应抚灵运，暂是忆嘉宾。","存信松犹小，缄哀草尚新。","鲤庭埋玉树，那忍见门人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-667d65f5-9f24-4abd-b635-214ba34533bb","tags":[]},{"id":"poem-928b46abb9fe436ed31c02cc","title":"过赵清献故居","author":"王柏","dynasty":"宋","verses":["隠隠数间清献宅，只在城东竹树中。","龟鹤不知何处去，谁将白鹿继高风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4afa4aeb-0d2e-4a90-a2ae-40ad40ce25af","tags":[]},{"id":"poem-928d02ff895f14faf7e5430b","title":"怀嵩楼","author":"常安民","dynasty":"宋","verses":["当年谩作嵩山想，末路难回瘴海身。","斜日西风总如昨，风流只欠倚栏人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0117225b-5363-4d4d-b916-987fb76ddf7e","tags":[]},{"id":"poem-929cd120677237c24c299e79","title":"虞美人·卷荷香淡浮烟渚","author":"鹿虔扆","dynasty":"五代","verses":["卷荷香淡浮烟渚，绿嫩擎新雨。","绣窗疏透晓风情，象床珍簟冷光轻，水纹平。","九疑黛色屏斜掩，枕上眉心敛。","不堪相望病将成，钿昏檀粉泪纵横，不胜情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-18","tags":[]},{"id":"poem-929ce3fec728deae742ccb6a","title":"秦州薛都督挽词","author":"沈佺期","dynasty":"唐","verses":["十里绛山幽，千年汾水流。","碑传门客建，劒是故人留。","陇树烟含夕，山门月对秋。","古来钟鼎盛，共尽一蒿丘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-781d15eb-381b-4c8e-8484-b5e072c8ba20","tags":[]},{"id":"poem-92acdb7348d94062a8dcdc71","title":"渔翁","author":"柳宗元","dynasty":"唐","verses":["渔翁夜傍西岩宿，晓汲清湘燃楚竹。","烟销日出不见人，[欸]乃一声山水绿。","回看天际下中流，岩上无心云相逐。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-51b1aeeb-9a66-412d-b15c-4afaa6c6b1d7","tags":["唐诗三百首","写人","七言古诗","山水"]},{"id":"poem-92b06be7bdf0a0381b53612c","title":"金陵图","author":"韦庄","dynasty":"唐","verses":["谁谓伤心画不成，画人心逐世人情。","君看六幅南朝事，老木寒云满故城。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4c5b328d-2ab8-4f4d-a0c2-627b6cb0c92b","tags":["隋・唐・五代","唐诗三百首","题画","七言绝句","咏史怀古","带有地名","地名"]},{"id":"poem-92b12bd6e4a29a9a1a1ce452","title":"柳梢青·数声𫛸鴂","author":"蔡伸","dynasty":"宋","verses":["数声𫛸鴂。","可怜又是，春归时节。","满院东风，海棠铺绣，梨花飘雪。","丁香露泣残枝，算未比、愁肠寸结。","自是休文，多情多感，不干风月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-206","tags":["宋词三百首"]},{"id":"poem-92bd4be2079f98dde9a9927d","title":"酬郭给事","author":"王维","dynasty":"唐","verses":["洞门高阁霭余辉，桃李阴阴柳絮飞。","禁里疎钟官舍晚，省中啼鸟吏人稀。","晨摇玉佩趋金殿，夕奉天书拜琐闱。","强欲从君无那老，将因卧病解朝衣。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7950a49f-f51d-4926-9d1e-e5f76b153829","tags":["唐诗三百首","酬和","七言律诗"]},{"id":"poem-92bfc94f89b6f9c785dc761f","title":"横吹曲辞 折杨柳","author":"张祜","dynasty":"唐","verses":["红粉青楼曙，垂杨仲月春。","怀君重攀折，非妾妒腰身。","舞带萦丝断，娇娥向叶嚬。","横吹凡几曲，独自最愁人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-afb30a8c-345b-471d-bf80-9f1828f8e097","tags":[]},{"id":"poem-92cc9de39fb1070008fe56a4","title":"李居士","author":"司空图","dynasty":"唐","verses":["高风只在五峰前，应是精灵降作贤。","万里无云惟一鹤，乡中同看却升天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-19935893-8dc1-47a4-b7ce-4637321baa65","tags":[]},{"id":"poem-92cff16ec972166c46ff8bd2","title":"鹧鸪天·借问枝头昨夜春","author":"石耆翁","dynasty":"宋","verses":["借问枝头昨夜春。","已传消息到柴门。","频看秀色无多艳，拖得清香不见痕。","山矗矗，水粼粼。","村南村北冷销魂。","人间不识春风面，羞见瑶台破月明。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-888","tags":[]},{"id":"poem-92d315e5e8a1e4812863e2d4","title":"桂枝香·登临送目","author":"王安石","dynasty":"宋","verses":["登临送目。","正故国晚秋，天气初肃。","千里澄江似练，翠峰如簇。","归帆去棹残阳里，背西风、酒旗斜矗。","彩舟云淡，星河鹭起，画图难足。","念往昔、繁华竞逐。","叹门外楼头，悲恨相续。","千古凭高，对此漫嗟荣辱。","六朝旧事随流水，但寒烟、芳草凝绿。","至今商女，时时犹唱，后庭遗曲。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-15","tags":["宋词三百首"]},{"id":"poem-92de76bba495cb0207bec81f","title":"列仙文 金母飞空歌","author":"孟郊","dynasty":"唐","verses":["驾我八景舆，歘然入玉清。","龙群拂霄上，虎旗摄朱兵。","逍遥三弦际，万流无暂停。","哀此去留会，劫尽天地倾。","当寻无中景，不死亦不生。","体彼自然道，寂观合大冥。","南岳挺直干，玉英曜颕精。","有任靡期事，无心自虚灵。","嘉会绛河内，相与乐未英。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4628c2c7-4349-42b8-92ab-e6a1bf0f6e7e","tags":["衡山"]},{"id":"poem-92debc240c5b2f2e9311f704","title":"赵康州徐夫子庙","author":"苗仲渊","dynasty":"宋","verses":["世惟忠与孝，训俗知所止。","杀身赵康州，锡类徐夫子。","虽非萃一门，死葬同闾里。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-adf69b4b-0693-4dbd-91be-1f37c61fa692","tags":[]},{"id":"poem-92e714bf2855ad848bdb1616","title":"山东兰若遇静公夜归","author":"唐求","dynasty":"唐","verses":["松门一径微，苔滑往来稀。","半夜闻钟后，浑身带雪归。","问寒僧接杖，辨语犬衔衣。","又是安禅去，呼童闭竹扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6b13138e-e63e-4232-89a9-552ad6f21002","tags":[]},{"id":"poem-92f70bb901432fc25c89a5a0","title":"念奴娇·洞庭青草","author":"张孝祥","dynasty":"宋","verses":["洞庭青草，近中秋、更无一点风色。","玉鉴琼田三万顷，著我扁舟一叶。","素月分辉，明河共影，表里俱澄澈。","悠然心会，妙处难与君说。","应念岭海经年，孤光自照，肝肺皆冰雪。","短发萧骚襟袖冷，稳泛沧浪空阔。","尽吸西江，细斟北斗，万象为宾客。","扣舷独笑，不知今夕何夕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-279","tags":["宋词三百首","洞庭湖"]},{"id":"poem-9303b1d0014898a697fb63d7","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["定获英奇不在多，然须设网遍山河。","禽虽一目罗中得，岂可空张一目罗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7bc113e9-7c38-4429-a9ad-eff7e88483da","tags":[]},{"id":"poem-9313d71809122279df6d64bc","title":"摊破诉衷情・诉衷情·夕阳低户水当楼","author":"蔡楠","dynasty":"宋","verses":["夕阳低户水当楼。","风烟惨淡秋。","乱云飞尽碧山留。","寒沙卧海鸥。","浑似画，只供愁。","相看空泪流。","故人如欲问安不。","病来今白头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-849","tags":[]},{"id":"poem-93141d1f3a5e98d331719eb2","title":"贺新郎·浪影龟纹皱","author":"吴文英","dynasty":"宋","verses":["浪影龟纹皱。","蘸平烟、青红半湿，枕溪窗牖。","千尺晴霞慵卧水，万叠罗屏拥绣。","漫几度、吴船回首。","归雁五湖应不到，问苍茫、钓雪人知否。","樵唱杳，度深秀。","重来趁得花时候。","记留连、空山夜雨，短亭春酒。","桃李新栽成蹊处，尽是行人去后。","但东阁、官梅清瘦。","欸乃一声山水绿，燕无言、风定垂帘昼。","寒正悄，亸吟袖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-480","tags":[]},{"id":"poem-9316ab5afbf51a0b0b56e8ca","title":"郊庙歌辞 祭[太]社乐章 雍和","author":"褚亮","dynasty":"唐","verses":["美报崇本，严恭展事。","受露疎坛，承风启地。","絜粢登俎，醇牺入馈。","介福远流，群生毕遂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4e16514b-49db-4319-a118-d8a6e866e300","tags":[]},{"id":"poem-9324ef7bf153910d7a98d85e","title":"宴韦司户山亭院","author":"高适","dynasty":"唐","verses":["人幽想灵山，意惬怜远水。","习静务为适，所居还复尔。","汲流涨华池，开酌宴君子。","苔迳试窥践，石屏可攀倚。","入门见中峰，携手如万里。","横琴了无事，垂钓应有以。","高馆何沈沈，飒然凉风起。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-482ab10e-32bb-455b-8208-204f55f6d37f","tags":[]},{"id":"poem-932ae5f47d5a099870364c33","title":"度涂山","author":"寇泚","dynasty":"唐","verses":["小年弄文墨，不识戎旅难。","一朝事鞞鼓，策马度涂山。","涂山横地轴，万里留荒服。","悠悠征斾远，𬴂骖一何速。","流月挥金戈，惊风折寒木。","行闻汉飞将，还向臯兰宿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-18678980-d18d-4d54-b981-0193b9476cbd","tags":[]},{"id":"poem-933053f96fec3fd9271088be","title":"题水仙梨花菊蒲萄栀子  其四","author":"释居简","dynasty":"宋","verses":["藤搴翠朵剪轻柔，小压涓涓翠玉流。","一石可偿千日醉，凉州未必似杨州。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-85946e51-e6ef-4853-86ea-1bb993f14453","tags":[]},{"id":"poem-933376ea545ca1bb4fd0f643","title":"村醉","author":"卢仝","dynasty":"唐","verses":["村醉黄昏归，健倒三四五。","摩娑莓苔背，嗔我惊尔不。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-da7785f1-3aaa-4274-a55a-da81028024df","tags":[]},{"id":"poem-933db770c74703fc2f8ddcd4","title":"江城子·老饕嗜酒若鸱夷","author":"李纲","dynasty":"宋","verses":["老饕嗜酒若鸱夷。","拣珠玑。","自蒸炊。","𥬠尽云腴，浮蚁在瑶卮。","有客相过同一醉，无客至，独中之。","曲生风味有谁知。","豁心脾。","展愁眉。","玉颊红潮，还似少年时。","醉倒不知天地大，浑忘却，是和非。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-560","tags":[]},{"id":"poem-9344ad12588ae51a13bf52c0","title":"郊庙歌辞 太清宫乐章 紫极舞","author":"不详","dynasty":"唐","verses":["至道生元气，重圆法混成。","无为观大象，冲用体常名。","仙乐临丹阙，云车出玉京。","灵符百代应，瑞节九贞迎。","宝运开皇极，天临映太清。","长垂一德庆，永庇万方宁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fd921ba1-15e1-4b4c-96e5-a127f6678ea7","tags":[]},{"id":"poem-9349a2a249d0306bb317546c","title":"女冠子·云罗雾縠","author":"薛昭蕴","dynasty":"五代","verses":["云罗雾縠，新授明威法箓，降真函。","髻绾青丝发，冠抽碧玉簪。","往来云过五，去往岛经三。","正遇刘郎使，启瑶缄。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-43","tags":[]},{"id":"poem-934ae5c036b0aa59802687e0","title":"幽思","author":"张碧","dynasty":"唐","verses":["金炉烟霭微，锦釭残影灭。","出户独裴回，落花满明月。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-74002940-307e-4d52-940e-0aeadf86e0c1","tags":[]},{"id":"poem-9360d698f517d52f0953df7b","title":"兵要望江南 《周易》占候第二十六（三十七首） 十","author":"易静","dynasty":"唐","verses":["子孙动，有气甚分明。","我若撃他全获捷，他来攻我败无门，我将立功勋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7d7fdcfd-0d98-42ec-98ff-42c289890500","tags":[]},{"id":"poem-93727213729c0c07aa5f7788","title":"陇西行四首 二","author":"陈陶","dynasty":"唐","verses":["誓扫匈奴不顾身，五千貂锦丧胡尘。","可怜无定河边骨，犹是春闺梦里人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fde30eaa-9b2c-47ce-ba49-c1356353ac9a","tags":["唐诗三百首","思念","战争","妇女","边塞","七言绝句"]},{"id":"poem-937575c72aaef0e4f54c1015","title":"莫相疑行","author":"杜甫","dynasty":"唐","verses":["男儿生无所成头皓白，牙齿欲落真可惜。","忆献三赋蓬莱宫，自怪一日声辉赫。","集贤学士如堵墙，观我落笔中书堂。","往时文彩动人主，此日饥寒趋路旁。","晚将末契托年少，当面输心背面笑。","寄谢悠悠世上儿，不争好恶莫相疑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-840f36d1-df6e-4cfe-87ac-692fc102ff44","tags":["厌倦","抒情","愤懑"]},{"id":"poem-937e3723a7a22a3f43adbbc5","title":"寄西岳白石僧","author":"马戴","dynasty":"唐","verses":["挂锡中峰上，经行踏石梯。","云房出定后，岳月在池西。","峭壁残霞照，欹松积雪齐。","年年著山屐，曾得到招提。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7455f507-16a8-41a1-bce9-03b1082ccda0","tags":[]},{"id":"poem-937f0b6346cd12cb60020d92","title":"代胡僧留别","author":"刘言史","dynasty":"唐","verses":["此地缘疎语未通，归时老病去无穷。","定知不彻南天竺，死在条支阴碛中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-85d5ca9c-bcd9-4cbc-b1dd-265dc92dc649","tags":[]},{"id":"poem-938ace5f7f0f89337d892320","title":"振鹭","author":"佚名","dynasty":"先秦","verses":["振鹭于飞，于彼西雍。我客戾止，亦有斯容。在彼无恶，在此无斁。庶几夙夜，以永终誉。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-277","tags":[]},{"id":"poem-938c11da26c6ef7320187125","title":"吊元鲁山 七","author":"孟郊","dynasty":"唐","verses":["箫韶太平乐，鲁山不虚作。","千古若有知，百年幸如昨。","谁能嗣教化，以此洗浮薄。","君臣贵深遇，天地有灵橐。","力运既艰难，德符方合漠。","名位苟虚旷，声明自销铄。","礼法虽相救，贞浓易糟粕。","哀哀元鲁山，毕竟谁能度。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-76b6053e-67dd-47eb-8bbd-057fb717e01d","tags":[]},{"id":"poem-939110243ad2f6ddc032e606","title":"元正  其一","author":"王柏","dynasty":"宋","verses":["开正又展一年期，霞脸醺醺酒半巵。","独坐晴窗无一事，呼童和墨写梅诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-79e72e87-88c9-4966-b3db-d6a3c7e93619","tags":[]},{"id":"poem-9395122917e23d02cc7ec900","title":"清源夫人赵氏挽词  其一","author":"王十朋","dynasty":"宋","verses":["全节忠臣配，崇宁宰相家。","哀能变国俗，贵不御铅华。","学佛穷三昧，然松教五车。","遗芳载彤管，名寿两俱遐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f37b4ee3-8cfe-44c3-87a0-94fe1627e176","tags":[]},{"id":"poem-9397b69fffe11b944dc88d78","title":"长安春","author":"崔道融","dynasty":"唐","verses":["长安牡丹开，绣毂辗晴雷。","若使花长在，人应看不回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3a56e675-4972-41f5-9b57-7a676203580a","tags":[]},{"id":"poem-9399b1c389169bb8d35380f8","title":"游天竺寺","author":"卢元辅","dynasty":"唐","verses":["水田十里学袈裟，秋殿千金俨释迦。","远客偏求月桂子，老人不记石莲花。","武林山价县隋日，天竺经文隶汉家。","苔壁娲皇炼来处，泐中修竹扫云霞。","（见《两浙金石志》卷二。","）（〖1〗石刻诗前原题「大唐杭州刺史卢元辅」九字。","〖2〗阮元《两浙金石志》：「右刻在下天竺神尼塔下磨崖，文九行，右行，正书，径二寸。","此诗《全唐诗》未载。","按卢元辅于德宗时自河南县令除杭州刺史，尝于武林山作见山亭，见《咸淳临安志》。","又《胥山碑铭》，元和十年卢元辅文，王遹书，见《舆地碑目》。","此疑元和时刻。","又《陜西通志》云：『卢元辅滑州人，曾为华州刺史。』","《郎官石柱题名》有金部郎中卢元辅。","白乐天有《卢元辅除杭州刺史制》，中云：『尝守商都，再领京县。』","皆其历官也。","石本『泐中修竹扫云霞』，『泐』字系原刻，『修竹』二字系改凿。","『大唐』二字亦添补。","《西湖志》作『洞中』，盖据文理，未见石刻也。」","〖3〗《杭州府志》引《武林石刻记》：「唐卢元辅《游天竺诗》，纵一尺八寸，横二尺，正书，字径二寸。」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-18e1e6e1-08a9-4458-95ef-52f097cb235a","tags":["西湖"]},{"id":"poem-93a6f8581cafc8d10f1c35a0","title":"宫词  其二","author":"张公庠","dynasty":"宋","verses":["朱字衙香伴玉𬬻，丁丁莲漏月来初。","交龙画烛摇红影，准拟君王夜读书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cf6e9e2c-d414-4660-85b7-61f11c6ca549","tags":[]},{"id":"poem-93aba1fd2fb34638a0cc93c6","title":"念奴娇·海云四敛","author":"张孝祥","dynasty":"宋","verses":["海云四敛，太清楼、极目一天秋色。","明月飞来云雾尽，城郭山川历历。","良夜悠悠，西风袅袅，银汉冰轮侧。","云霓三弄，广寒宫殿长笛。","偏照紫府瑶台，香笼玉座，翠霭迷南北。","天上人间凝望处，应有乘风归客。","露滴金盘，凉生玉宇，满地新霜白。","壶中清赏，画檐高挂虚碧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-369","tags":[]},{"id":"poem-93b55ec8b6d57195ab0e345c","title":"渔家傲·红粉墙头花几树","author":"欧阳修","dynasty":"宋","verses":["红粉墙头花几树。","落花片片和惊絮。","墙外有楼花有主。","寻花去。","隔墙遥见秋千侣。","绿索红旗双彩柱。","行人只得偷回顾。","肠断楼南金锁户。","天欲暮。","流莺飞到秋千处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-650","tags":[]},{"id":"poem-93ba44159fb65992fbe1c275","title":"缕缕金","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["时不利，命何乖！双亲在途路上，怕他灾。","(末丑唱)此是弥陀寺，略停车盖。","(合)办虔心恳祷拜莲台，特来赴佛会。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5199","tags":[]},{"id":"poem-93bc505870fced178491a5be","title":"四月二十日与客来城南积潦方盛湖光恬然如平时泛舟终日分韵得水字","author":"张栻","dynasty":"宋","verses":["泽国盛梅雨，涨潦弥两涘。","常时侵溢患，乃复到城市。","纳湖迫西𬮱，冲突固其理。","今年筑隄防，楗石细积累。","艰辛迄崇成，龟鱼亦欢喜。","节宣有程度，盈缩无壅底。","昨宵水没岸，民居例迁徙。","走马来问讯，屹若坚城垒。","江涛从渺茫，湖光自清泚。","小舟足游泳，新荷方薿薿。","嘉我二三客，共此风日美。","相期寂寞滨，雅意淡如水。","念言隄防功，得失乃如彼。","而况检身者，讵可忘所止。","明朝更哦诗，斯言或当纪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d2be44a8-940d-48e3-8c58-26aa018da7d2","tags":[]},{"id":"poem-93c0f237d312731d5d70f800","title":"偈","author":"丰禅师","dynasty":"唐","verses":["骏马机前异，游人肘后悬。","既参云外客，试为老僧看。","（《景德传灯录》卷二十三、《五灯会元》卷十五）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f5e32596-f21a-4833-9feb-31d9f45f7392","tags":[]},{"id":"poem-93c961045e1e118cd4d84409","title":"雝","author":"佚名","dynasty":"先秦","verses":["有来雝雝，至止肃肃。相维辟公，天子穆穆。于荐广牡，相予四祀。假哉皇考！绥予孝子。","宣哲维人，文武维后。燕及皇天，克昌厥后。绥我眉寿，介以繁祉，既右烈考，亦右文母。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-281","tags":[]},{"id":"poem-93cbc6a9672fefd519fa428b","title":"春光好·苹叶软","author":"和凝","dynasty":"五代","verses":["苹叶软，杏花明，画船轻。","双浴鸳鸯出绿汀，棹歌声。","春水无风无浪，春天半雨半晴。","红粉相随南浦晚，几含情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-27","tags":[]},{"id":"poem-93d024b3eeed0ba2db51aada","title":"郊庙歌辞 享太庙乐章 景云舞","author":"张说","dynasty":"唐","verses":["景云霏烂，告我帝符。","噫帝冲德，与天为徒。","笙镛遥远，俎豆虚无。","春秋孝献，回复此都。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3ff56a31-51e0-4926-a44e-73635f47c545","tags":[]},{"id":"poem-93d9730078fdf8eb2eef5602","title":"题子敬范新妇唐摹帖三首  其三","author":"米芾","dynasty":"宋","verses":["直裂纹匀真古纸，跋印多时俗眼美。","诚悬尚复误疑似，有渭方能辨泾水。","真伪头面摸趺趾，久假中分辨愚智。","宝轴时开心一洗，百氏何人传至米。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0559e5e7-c998-43d4-922a-5708271385e7","tags":[]},{"id":"poem-93dc6654335043770583eb1c","title":"一庵","author":"释居简","dynasty":"宋","verses":["太极含三示极谈，初无一字可名庵。","明明未画前消息，才落思惟便别参。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-403c75f9-1780-4458-ac9d-9281fcd0e3dd","tags":[]},{"id":"poem-93e4d33eedbc9a91ee81d603","title":"琴歌","author":"李颀","dynasty":"唐","verses":["主人有酒欢今夕，请奏鸣琴广陵客。","月照城头乌半飞，霜凄万树风入衣。","铜𬬻华烛烛增辉，初弹渌水后楚妃。","一声已动物皆静，四座无言星欲稀。","清淮奉使千余里，敢告云山从此始。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7d906794-b4d1-4922-9c59-eee5b19602ad","tags":["唐诗三百首","音乐","宴会","七言古诗"]},{"id":"poem-93eb51ac9938565cd434959c","title":"浣溪沙·七夕年年信不违","author":"毛文锡","dynasty":"五代","verses":["七夕年年信不违，银河清浅白云微，蟾光鹊影伯劳飞。","每恨蟪蛄怜婺女，几回娇妒下鸳机，今宵嘉会两依依。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-24","tags":[]},{"id":"poem-93fa1e6a719b2d227aaec777","title":"送卢少府之任巩洛","author":"李洞","dynasty":"唐","verses":["从知东甸尉，铨注似恩除。","带土移嵩术，和泉送尹鱼。","印床寒鹭宿，壁记醉僧书。","堂下诸昆在，无妨候起居。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-05a2426e-5d9f-4885-9377-136bcea01baa","tags":[]},{"id":"poem-93fbba154f808dd382e75aad","title":"二三","author":"王梵志","dynasty":"唐","verses":["尊人对客饮，卓立莫东西。","（「卓立」，斯三三九三卷作「侧立」。","）使唤须依命，弓身莫不齐。","（「弓身」，伯三五五八、伯三六五六、斯四六六九卷作「躬身」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5a120593-720e-4811-a28b-b869a9c8bc84","tags":[]},{"id":"poem-941ddba3667aecf00576dcce","title":"望商山路","author":"司空曙","dynasty":"唐","verses":["南见青山道，依然去国时。","已甘长避地，谁料有还期。","雨霁残阳薄，人愁独望迟。","空残华发在，前事不堪思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-158d2496-f9df-4212-9997-7000227153dd","tags":[]},{"id":"poem-94278ba59678bf5b11ec52c6","title":"奉和御制麟德殿宴百僚应制","author":"尚宫宋氏若昭","dynasty":"唐","verses":["垂衣临八极，肃穆四门通。","自是无为化，非关辅弼功。","修文招隐伏，尚武殄妖凶。","德炳韶光炽，恩沾雨露浓。","衣冠陪御宴，礼乐盛朝宗。","万寿称觞举，千年信一同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8a5d0a21-2700-46ec-b018-e7dc9329251e","tags":[]},{"id":"poem-942f7646fd6c0b79f006d18d","title":"经费拾遗旧隐","author":"胡骈","dynasty":"唐","verses":["林下茅斋已半倾，九华幽迳少人行。","不将冠劒为荣事，只向烟萝寄此生。","松竹渐荒池上色，琴书徒立世间名。","白杨风起秋山暮，时复哀猨啼一声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f5d28ce3-202c-4072-a26c-7d7100cae796","tags":[]},{"id":"poem-9430248724276775925d4fe5","title":"咏史诗 滹沱河","author":"胡曾","dynasty":"唐","verses":["光武经营业未兴，王郎兵革正凭陵。","须知后汉功臣力，不及滹沱一片冰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9db4fe23-a3be-4b05-87ef-282f72f785f3","tags":[]},{"id":"poem-94302e3ebe110ed5530a2446","title":"望蓟门","author":"祖咏","dynasty":"唐","verses":["燕台一望客心惊，箫鼓喧喧汉将营。","万里寒光生积雪，三边曙色动危旌。","沙场烽火连胡月，海畔云山拥蓟城。","少小虽非投笔吏，论功还欲请长缨。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6beb5cc2-ae49-4e23-952a-1cb92fa11512","tags":["唐诗三百首","七言律诗","冬天","边塞"]},{"id":"poem-943670610465755a3cc22769","title":"山中酬人","author":"张籍","dynasty":"唐","verses":["山中日暖春鸠鸣，逐水看花任意行。","向晚归来石窗下，菖蒲叶上见题名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-042adab4-fd33-403a-81fb-9facc9416757","tags":[]},{"id":"poem-943de49ab565a4e0725f5957","title":"九章·哀郢","author":"屈原","dynasty":"先秦","verses":["皇天之不纯命兮，何百姓之震愆？","民离散而相失兮，方仲春而东迁。","去故乡而就远兮，遵江夏以流亡。","出国门而轸怀兮，甲之鼌吾以行。","发郢都而去闾兮，怊荒忽其焉极？","楫齐扬以容与兮，哀见君而不再得。","望长楸而太息兮，涕淫淫其若霰。","过夏首而西浮兮，顾龙门而不见。","心婵媛而伤怀兮，眇不知其所跖。","顺风波以从流兮，焉洋洋而为客。","凌阳侯之汜滥兮，忽翱翔之焉薄。","心絓结而不解兮，思蹇产而不释。","将运舟而下浮兮，上洞庭而下江。","去终古之所居兮，今逍遥而来东。","羌灵魂之欲归兮，何须臾而忘反。","背夏浦而西思兮，哀故都之日远。","登大坟以远望兮，聊以舒吾忧心。","哀州土之平乐兮，悲江介之遗风。","当陵阳之焉至兮，淼南渡之焉如？","曾不知夏之为丘兮，孰两东门之可芜？","心不怡之长久兮，忧与愁其相接。","惟郢路之辽远兮，江与夏之不可涉。","忽若不信兮，至今九年而不复。","惨郁郁而不通兮，蹇侘傺而含戚。","外承欢之汋约兮，谌荏弱而难持。","忠湛湛而愿进兮，妒被离而鄣之。","尧舜之抗行兮，瞭杳杳而薄天。","众谗人之嫉妒兮，被以不慈之伪名。","憎愠惀之修美兮，好夫人之慷慨。","众踥蹀而日进兮，美超远而逾迈。","乱曰：曼余目以流观兮，冀一反之何时？","鸟飞反故乡兮，狐死必首丘。","信非吾罪而弃逐兮，何日夜而忘之？"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-15","tags":[]},{"id":"poem-9445720aab389e6461946b37","title":"初秋寓直三首 三","author":"郑畋","dynasty":"唐","verses":["幽阁焚香万虑凝，下帘胎息过禅僧。","玉堂分照无人后，消尽金盆一碗冰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d5311784-d491-40ae-bea2-0888c5dcf2d4","tags":[]},{"id":"poem-9445ecf8dfb1e9495879a79c","title":"杂诗二首 二","author":"卢象","dynasty":"唐","verses":["君家御沟上，垂柳夹朱门。","列鼎会中贵，鸣珂朝至尊。","死生在片议，穷达由一言。","须识苦寒士，莫矜狐白温。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-efaef8c1-a7b0-424d-87bd-44283b6c4fb8","tags":[]},{"id":"poem-944b1014b6e19750f93c419d","title":"句  其六","author":"滕元发","dynasty":"宋","verses":["主人留客醉，酒美蟹螯肥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-258e83d2-7c4d-4915-bc1a-2f0192bd3822","tags":[]},{"id":"poem-94555214c2b93801cfcff902","title":"对月了残经赞  其一","author":"释了惠","dynasty":"宋","verses":["破微尘出大经卷，一弹指顷千百遍。","只因错认月为灯，至今展卷遮羞面。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2d301b54-d7c7-4ca5-8f39-a2be2fbfdcfa","tags":[]},{"id":"poem-9456512535218d34d5a355ce","title":"春闺","author":"沈佺期","dynasty":"唐","verses":["铁马三军去，金闺二月还。","边愁离上国，春梦失阳关。","池水琉璃净，园花玳瑁斑。","岁华空自掷，忧思不胜颜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fd19c09d-4d11-4209-870a-0fc03e73e647","tags":[]},{"id":"poem-9465ee6893bb342e89239677","title":"题城南书院三十四咏  其二六","author":"张栻","dynasty":"宋","verses":["拍堤水满草茸茸，尽日野航西复东。","欲去未须愁日暮，月明波面更溶溶。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f6e9bd5a-7f7d-4417-a372-658117e549de","tags":[]},{"id":"poem-947b8c39aab5efcc43916302","title":"游仙窟诗 手中扇赠文成","author":"崔十娘","dynasty":"唐","verses":["合欢游璧水，同心侍华阙。","飒飒似朝风，团团如夜月。","鸾姿侵雾起，鹤影排空发。","希君掌中握，勿使恩情歇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ceb5d266-e41d-4d9b-b49d-fe831ba96d8c","tags":[]},{"id":"poem-947d1715e5b08f93ea7b5f45","title":"韩魏公生于泉南州宅故未有祠于典为阙郡圃有庵名大隠即之以祠八月戊子率同僚祀之","author":"王十朋","dynasty":"宋","verses":["天开我宋太平基，紫府真人下应期。","河朔魁梧出真相，泉南葱鬰产奇儿。","梦符蚌腹生珠夜，事应台躔捧日时。","紫帽清源发光采，郡园深处立新祠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c0f2e48d-060d-4723-9b6d-7a9ab5926013","tags":[]},{"id":"poem-948182e9de4536502d9a1411","title":"潼关吏","author":"杜甫","dynasty":"唐","verses":["士卒何草草，筑城潼关道。","大城铁不如，小城万丈余。","借问潼关吏，修关还备胡。","要我下马行，为我指山隅。","连云列战格，飞鸟不能逾。","胡来但自守，岂复忧西都。","丈人视要处，窄狭容单车。","艰难奋长戟，万古用一夫。","哀哉桃林战，百万化为鱼。","请嘱防关将，慎勿学哥舒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-19c2a99b-507a-415a-8e66-1477861f5d71","tags":["士卒","战争","赞美","边疆"]},{"id":"poem-94845f79b586405459de728e","title":"菩萨蛮·园林寂寂春归去","author":"苏庠","dynasty":"宋","verses":["园林寂寂春归去。","蒙蒙柳下飞香絮。","野水接云横。","绿烟啼晓莺。","江南𫛸鴂梦。","山色朝来重。","小艇小湾头。","苹花苹叶洲。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-689","tags":[]},{"id":"poem-9489a5aefdaa28b6b070c37d","title":"咏古十六首  其一五","author":"华镇","dynasty":"宋","verses":["高柳何葱蒨，袅袅章台端。","眉叶荫紫极，条丝拂朱栏。","何以谢松竹，挠弱惭岁寒。","既乏贞固姿，枝叶何足观。","小人殉利欲，俛仰如转丸。","苟非社稷臣，祸患宁肯干。","蒲山已归觐，黎阳尚盘桓。","当时方寸地，明明赤如丹。","飙举冠凌烟，腾芳臭如兰。","一言失其所，功名两雕残。","高帝论平阳，刘氏终以安。","英公负文皇，武氏为世患。","无忌问赵相，侯嬴起长叹。","白首不可保，知人良独难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fb8c0993-117f-4541-8ae6-6b9f5ca6b222","tags":[]},{"id":"poem-948bdce15ccdb270d6152721","title":"庆佳节·芳菲节","author":"张先","dynasty":"宋","verses":["芳菲节。","芳菲节。","天意应不虚设。","对酒高歌玉壶阙。","慎莫负、狂风月。","人间万事何时歇。","空赢得、鬓成雪。","我有闲愁与君说。","且莫用、轻离别。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-295","tags":[]},{"id":"poem-949549ea1deb4639c534fb9a","title":"风入松","author":"皎然","dynasty":"唐","verses":["西岭松声落日秋，千枝万叶风飗飗。","美人援琴弄成曲，写得松间声断续。","声断续，清我魂，流波坏陵安足论。","美人夜坐月明里，含少商兮点清征。","风何凄兮飘飘，搅寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-fd8db3ba-96ed-4396-94bf-a52fddf5e125","tags":[]},{"id":"poem-94954c6fb0f3276f13a855d5","title":"西江月·住想修行布施","author":"张伯端","dynasty":"宋","verses":["住想修行布施，果报不离天人。","恰如仰箭射浮云。","坠落祗缘力尽。","争似无为实相，还须返朴归淳。","境忘情性任天真。","以证无生法忍。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-989","tags":[]},{"id":"poem-9496387db75906b8ee6dd729","title":"谒金门·春漏促","author":"韦庄","dynasty":"五代","verses":["春漏促，金烬暗挑残烛。","一夜帘前风撼竹，梦魂相断续。","有个娇娆如玉，夜夜绣屏孤宿。","宋袍琵琶寻旧曲，远山眉黛绿。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-0","tags":[]},{"id":"poem-949a5e1ae6767a51f7d338a8","title":"□□","author":"佚名","dynasty":"唐","verses":["恨到荒城一闭关，乡园阻隔万重山。","咫尺音书犹不达，梦魂何处得归还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9f0687c4-7fce-4931-9246-4f3855dbd527","tags":[]},{"id":"poem-949e1bdccb8ab0f0eebbc5dd","title":"陈情献中丞","author":"喻坦之","dynasty":"唐","verses":["孤拙竟何营，徒希折桂名。","始终谁肯荐，得失自难明。","贡乏雄文献，归无瘠土耕。","沧江长发梦，紫陌久慙行。","意纵求知切，才惟惧鉴精。","五言非琢玉，十载看迁莺。","取进心甘钝，伤嗟骨每惊。","尘襟痕积泪，客鬓白新茎。","顾盼身堪教，吹嘘羽觉生。","依门情转切，荷德力须倾。","奖善犹怜贡，垂恩必不轻。","从兹便提挈，云路自生荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-65fd2bb1-6ff8-4e39-ab8b-d35acb120d6b","tags":[]},{"id":"poem-94a7581e698b5233139bc445","title":"泛舟","author":"朱熹","dynasty":"宋","verses":["昨夜江边春水生，艨艟巨舰一毛轻。","向来枉费推移力，此日中流自在行。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-泛舟","tags":[]},{"id":"poem-94aa80027c151671c326ce98","title":"永明山居诗（六十九首） 八","author":"延寿","dynasty":"唐","verses":["碧峤经年常寂寂，更无闲事可相于。","超伦每效高僧行，得力难忘古佛书。","落叶乱渠凭水荡，浮云翳月倩风除。","方知懒与真空合，一衲闲披憇旧庐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-01b94f97-5e13-4e74-b35f-39273e5a9361","tags":[]},{"id":"poem-94ab928710a3b7ace66d051c","title":"天香·孤峤蟠烟","author":"王沂孙","dynasty":"宋","verses":["孤峤蟠烟，层涛蜕月，骊宫夜采铅水。","讯远槎风，梦深薇露，化作断魂心字。","红瓷候火，还乍识、冰环玉指。","一缕萦帘翠影，依稀海天云气。","几回娇半醉。","翦春灯、夜寒花碎。","更好故溪飞雪，小窗深闭。","荀令如今顿老，总忘却、樽前旧风味。","谩惜馀熏，空篝素被。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-248","tags":["宋词三百首"]},{"id":"poem-94ad4094790d12a21fe31463","title":"独孤常州北亭","author":"张南史","dynasty":"唐","verses":["北洫敞高明，凭轩见野情。","朝回五马迹，更胜百花名。","海树凝烟远，湖田见鹤清。","云光侵素壁，水影荡闲楹。","俗赖褰帷谒，人欢倒屣迎。","始能崇结构，独有谢宣城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1b7e6f4d-499f-4489-a106-c60a0532087a","tags":[]},{"id":"poem-94b25f390f28902b208724b5","title":"暗香·旧时月色","author":"姜夔","dynasty":"宋","verses":["旧时月色。","算几番照我，梅边吹笛。","唤起玉人，不管清寒与攀摘。","何逊而今渐老，都忘却、春风词笔。","但怪得、竹外疏花，香冷入瑶席。","江国。","正寂寂。","叹寄与路遥，夜雪初积。","翠尊易泣。","红萼无言耿相忆。","长记曾携手处，千树压、西湖寒碧。","又片片、吹尽也，几时见得。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-135","tags":["宋词三百首","西湖"]},{"id":"poem-94b37070c86d4a3742946a5c","title":"四边静","author":"萧德祥《小孙屠》","dynasty":"元","verses":["将它短招读一遍，把词因好生看。","休要顺人情，依法自行遣(和)。","这场罪愆，怎生觯免？一一与招成，三年待决断。","(生)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8644","tags":[]},{"id":"poem-94b6cd4ed0831f448d43180a","title":"寄华阴姚少府","author":"喻坦之","dynasty":"唐","verses":["泰华当公署，为官兴可知。","砚和青霭冻，帘对白云垂。","峻掌光浮日，危莲影入池。","料于三考内，应惜德音移。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ee9b5cf7-035e-42fd-8499-ab7569c9bf4f","tags":[]},{"id":"poem-94c47b819eb2821ebfa1e306","title":"赋得浮桥","author":"太宗皇帝","dynasty":"唐","verses":["岸曲非千里，桥斜异七星。","暂低逢辇度，还高值浪惊。","水摇文鹢动，缆转锦花萦。","远近随轮影，轻重应人行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0c1d43ec-220c-4983-a6f9-e4e55631ad44","tags":[]},{"id":"poem-94c910366e13a96150c6c1ce","title":"蝉","author":"李商隐","dynasty":"唐","verses":["本以高难饱，徒劳恨费声。","五更疎欲断，一树碧无情。","薄宦梗犹泛，故园芜已平。","烦君最相警，我亦举家清。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b3de619f-cc8b-457d-942b-49f06651aba4","tags":["唐诗三百首","咏物","咏物诗","五言律诗"]},{"id":"poem-94cc19661bccc6bfeda8c405","title":"教池回·云淡天低","author":"史浩","dynasty":"宋","verses":["云淡天低，疏雨乍霁，桃溪嫩绿蒙茸。","珠帘映画毂，金勒耀花骢。","绕湖上、罗衣隘香风。","擘波双引蛟龙。","寻奇处，高标锦段，各骋英雄。","缥缈初登彩舫，箫鼓沸，群仙玉佩丁东。","夕阳中、拚一饮千锺。","看看见、璧月穿林杪，十洲三岛舂容。","醉归去，双旌摇曳，夹路金笼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-103","tags":[]},{"id":"poem-94cd46bdf5f71cd454646c48","title":"蚕妇吟","author":"谢枋得","dynasty":"唐","verses":["子规啼彻四更时，起视蚕稠怕叶稀。","不信楼头杨柳月，玉人歌舞未曾归。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-蠶婦吟","tags":[]},{"id":"poem-94ced6ca","title":"己亥杂诗·其五","author":"龚自珍","dynasty":"清","verses":["浩荡离愁白日斜，吟鞭东指即天涯。","落红不是无情物，化作春泥更护花。"],"enabled":true,"collection":"历代名篇","source":"龚自珍《定盦全集》诗《己亥杂诗》其五。","tags":["抒怀"]},{"id":"poem-94d2fad767e25f0c6b1163b6","title":"大叔于田","author":"佚名","dynasty":"先秦","verses":["叔于田，乘乘马。执辔如组，两骖如舞。叔在薮，火烈具举。襢裼暴虎，献于公所。将叔勿狃，戒其伤女。","叔于田，乘乘黄。两服上襄，两骖雁行。叔在薮，火烈具扬。叔善射忌，又良御忌。抑罄控忌，抑纵送忌。","叔于田，乘乘鸨。两服齐首，两骖如手。叔在薮，火烈具阜。叔马慢忌，叔发罕忌，抑释掤忌，抑鬯弓忌。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-77","tags":[]},{"id":"poem-94e047789dfd5b0d6103fe54","title":"菊","author":"李山甫","dynasty":"唐","verses":["篱下霜前偶得存，忍教迟晚避兰荪。","也销造化无多力，未受阳和一点恩。","栽处不容依玉砌，要时还许上金尊。","陶潜殁后谁知己，露滴幽丛见泪痕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-fd364eb0-a4f3-42ef-87b3-bc568f503e1a","tags":[]},{"id":"poem-94eee31354d3500523cb7670","title":"扈从书事","author":"綦崇礼","dynasty":"宋","verses":["扈从官班近，囏难报效微。","又同陪法驾，复共著征衣。","举目江山好，伤心井社非。","何当戎马定，却作故乡归。","负郭田园美，迎霜雉兔肥。","风尘嗟澒洞，梦寐怅依稀。","圣主兴皇祚，群公翊政机。","时平当自劾，还采故山薇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-41e71f85-0952-4b91-9ee1-207f7cc5f993","tags":[]},{"id":"poem-94f992074a4adc11f3a933e1","title":"赠亮首坐","author":"王十朋","dynasty":"宋","verses":["雪顶庞眉八十余，五峰深处结精庐。","阅人老眼能青白，赠我严公一轴书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-494ff1c9-5a9d-4445-967f-f315f0515e79","tags":[]},{"id":"poem-95001b4295e3c01e85b168fa","title":"哭胡处士","author":"曹松","dynasty":"唐","verses":["丘中久不起，将谓诏书来。","及见凌云说，方知掩夜台。","白衣归北路，玄造亦遗才。","世上亡君后，诗声更大哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-814e7769-7855-4fbe-87a9-ad85e3f78933","tags":[]},{"id":"poem-951101bc82c73bc501d7f0f0","title":"扶病春亭","author":"刘言史","dynasty":"唐","verses":["强梳稀发著纶巾，舍杖空行试病身。","花间自欲裴回立，穉子牵衣不许人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-96827e11-bc6c-4705-b95c-64c46f9f1ea8","tags":[]},{"id":"poem-9512cd668c7a0459bc3308ab","title":"郊天回","author":"鲍溶","dynasty":"唐","verses":["日动萧烟上泰坛，帝从黄道整和銮。","风前貔武回雕仗，云里神龙起画竿。","金鸟赦书鸣九夜，玉山寿酒舞千官。","始知报本终朝礼，旧典时巡只自难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f4a34239-17b5-4533-a0b5-56220a62bb06","tags":[]},{"id":"poem-95155674cf329fd0d560f7d9","title":"同从弟销南斋玩月忆山阴崔少府","author":"王昌龄","dynasty":"唐","verses":["高卧南斋时，开帷月初吐。","清辉淡水木，演漾在窗户。","苒苒几盈虚，澄澄变今古。","美人清江畔，是夜越吟苦。","千里其如何，微风吹兰杜。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e2fec465-cea1-4829-b12d-3ba37a267562","tags":["唐诗三百首","五言古诗","月亮","怀人"]},{"id":"poem-951a777fc60e3488872157cd","title":"酬盘隠别驾  其一","author":"释居简","dynasty":"宋","verses":["早悟玄元一曰慈，持身有本是无私。","戒将重帚伤蝼蚁，弗买生鱼喂鹭鸶。","桂实松高宜寿此，竹清梅瘦亦如斯。","吟成换得神仙骨，不枉凭阑撚断髭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-581162b0-267c-4435-a936-f5e9876e9899","tags":[]},{"id":"poem-952615de8614297146d507ab","title":"时兴","author":"杨贲","dynasty":"唐","verses":["贵人昔未贵，咸愿顾寒微。","及自登枢要，何曾问布衣。","平明登紫阁，日晏下彤闱。","扰扰路傍子，无劳歌是非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c05348b3-0526-4cf9-b443-eb0aecf607b5","tags":[]},{"id":"poem-952a0f7db069e7d616b19ed3","title":"蝶恋花·北斗秋横云髻影","author":"吴文英","dynasty":"宋","verses":["北斗秋横云髻影。","莺羽衣轻，腰减青丝剩。","一曲游仙闻玉磬。","月华深院人初定。","十二阑干和笑凭。","风露生寒，人在莲花顶。","睡重不知残酒醒。","红帘几度啼鸦暝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-443","tags":[]},{"id":"poem-955ceda4444bed685c0ce3fb","title":"送人东游","author":"温庭筠","dynasty":"唐","verses":["荒戍落黄叶，浩然离故关。","高风汉阳渡，初日郢门山。","江上几人在，天涯孤櫂还。","何当重相见，尊酒慰离颜。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-315bc0e1-f76c-49d5-9940-b212e5f9c2ae","tags":["唐诗三百首","友情","送别","五言律诗","惜别","秋天"]},{"id":"poem-955da2000148c9ca45c195a6","title":"白田西忆楚州使君弟","author":"李嘉祐","dynasty":"唐","verses":["山阳郭里无潮，野水自向新桥。","鱼网平铺荷叶，鹭鸶闲步稻苗。","秣陵归人惆怅，楚地连山寂寥。","却忆士龙宾阁，清琴绿竹萧萧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cb4f4170-b86e-44bf-813e-516858bef701","tags":[]},{"id":"poem-9568e517d66beb25c7895825","title":"菩萨蛮·罗衣隐约金泥画","author":"魏承班","dynasty":"五代","verses":["罗衣隐约金泥画，玳筵一曲当秋夜。","声战觑人娇，云袅翠翘。","酒醺红玉软，眉翠秋山远。","绣幌麝烟沉，谁人知两心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-49","tags":[]},{"id":"poem-956bdbf9a58a6323f99d48bc","title":"发成都  其二","author":"刘望之","dynasty":"宋","verses":["欲洗羁愁只自醒，郫筒酒好信虚名。","江阳春色论千户，价比西州却未轻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-be16ad35-9ebc-4b87-9810-0841446c7b87","tags":[]},{"id":"poem-9574c0c3230ee46c32637dd6","title":"南山","author":"佚名","dynasty":"先秦","verses":["南山崔崔，雄狐绥绥。鲁道有荡，齐子由归。既曰归止，曷又怀止？","葛屦五两，冠緌双止。鲁道有荡，齐子庸止。既曰庸止，曷又从止？","蓺麻如之何？衡从其亩。取妻如之何？必告父母。既曰告止，曷又鞠止？","析薪如之何？匪斧不克。取妻如之何？匪媒不得。既曰得止，曷又极止？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-100","tags":[]},{"id":"poem-9577db15d7ae01202fa269d6","title":"送禀上人游越","author":"皎然","dynasty":"唐","verses":["云泉谁不赏，独见尔情高。","投石轻龙窟，临流笑鹭涛。","折荷为片席，洒水净方袍。","剡路逢禅侣，多应问我曹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9eb38dff-a8cc-4790-9e6f-810abaf53f82","tags":[]},{"id":"poem-958145204618d9b4e6eefe3c","title":"花犯·小娉婷","author":"吴文英","dynasty":"宋","verses":["小娉婷，清铅素靥，蜂黄暗偷晕。","翠翘敧鬓。","昨夜冷中庭，月下相认。","睡浓更苦凄风紧。","惊回心未稳。","送晓色、一壶葱蒨，才知花梦准。","湘娥化作此幽芳，凌波路，古岸云沙遗恨。","临砌影，寒香乱、冻梅藏韵。","熏炉畔、旋移傍枕，还又见、玉人垂绀鬒。","料唤赏、清华池馆，台杯须满引。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-442","tags":["宋词三百首"]},{"id":"poem-9582144c95e77e5f983626c4","title":"南歌子·雨洗溪光净","author":"谢逸","dynasty":"宋","verses":["雨洗溪光净，风掀柳带斜。","画楼朱户玉人家。","帘外一眉新月、浸梨花。","金鸭香凝袖，铜荷烛映纱。","凤盘宫锦小屏遮。","夜静寒生春笋、理琵琶。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-611","tags":[]},{"id":"poem-958c45afdbcc01493dace329","title":"山友赠藓花冠","author":"项斯","dynasty":"唐","verses":["尘污出华发，慙君青藓冠。","此身闲未得，终日戴应难。","好就松阴挂，宜当枕石看。","会须寻道士，簪去绕霜坛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-968139f4-44e2-401d-b6fb-198b2e829282","tags":[]},{"id":"poem-95908584995fa64b7106c8a7","title":"洋州三十景 菡萏亭","author":"鲜于侁","dynasty":"宋","verses":["夏绿分照水，秋香仍满地。","吴宫谁教战，一一尽妖媚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a81214f8-d984-4fce-9140-08f1c6e890f6","tags":[]},{"id":"poem-959c891bc4c4a7cab80419f6","title":"闻友人驾前及第","author":"贯休","dynasty":"唐","verses":["见心知命好，一别隔烟波。","世乱无全士，君方掇大科。","早随銮辂转，莫恋蜀山多。","必贡安时策，忠言奈尔何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-37bc4a26-3b08-424c-9267-a4615ff8ef97","tags":[]},{"id":"poem-959ca2b7df5f97517d4963a6","title":"夜","author":"徐夤","dynasty":"唐","verses":["日坠虞渊烛影开，沈沈烟雾压浮埃。","剡川雪满子猷去，汉殿月生王母来。","簷挂蛛丝应渐织，风吹萤火不成灰。","愁人莫道何时旦，自有钟鸣漏滴催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-1309b952-d792-4b93-805e-6808995b66cb","tags":[]},{"id":"poem-95a176a9d851e82c1b6cc834","title":"赠乐使君","author":"马云奇","dynasty":"唐","verses":["知君桃李遍成蹊，故托乔林此处栖。","虽然灌木凌云秀，会有寒鵶夜夜啼。","（〖1〗以上十三首诗从伯二五五五残卷中录出。","第一首下题名马云奇。","因为这些诗格调相似，其中有多首咏及被吐蕃拘系之事，故可定为一人作品。","这个残卷中还有五十九首伕名诗〖已编入第二卷〗，也是唐代中期我国国内民族战争中被吐蕃拘系的敦煌汉族人所写。","这些诗，过去未见著录，《全唐诗》也没有收入。","有三生前在巴黎图书馆将这一残卷全文录出，以后又作过整理加工，惜未最后定稿。","现据舒学同志的整理稿校对后辑入本卷。","〖2〗马云奇的生平目前虽无资料可查，但从这十三首的内容来看，尤其是从第一首《怀素师草书歌》所写的怀素情况来看，诗的写作时间与卷二那五十九首伕名诗大致相近，即在公元七五八--七八一年吐蕃逐渐侵吞河陇地区，而西州、沙州尚为唐军坚守之时。","（对马云奇诗及卷二无名氏残诗集的作者近年有些学者提出了不同看法。","现摘录柴剑虹、潘重规的文章如次，以供参考。","〖3〗）（柴剑虹《敦煌伯二五五五卷「马云奇诗」辨》〖刊《中华文史论丛》一九八四年第二辑〗认为，伯二五五五卷中马云奇的诗只有《怀素师草书歌》一首，其余十二首与另外五十九首一样，均是一位佚名的落蕃人所作。","他指出，该卷第一部分正面抄唐人诗一百五十六首，文两篇，背面抄诗三十二首，应是唐人诗文选集残卷。","从抄写情况看，正面显系一人笔迹。","那五十九首坆名诗抄写格式稍异，大多数诗题完整，且高出一格抄，内容又紧密衔接，作者自抄的可能性很大。","背面所抄，署名马云奇的只有《怀素师草书歌》一首，此诗诗题低两格抄，署名又和诗题空两格，且用大字抄写。","《白云歌》等十二首抄于此诗之左，并无署名，而且马上改变了抄写格式，字体也缩小了一倍，诗题顶格。","这十二首诗从抄写格式到内容、风格均与马云奇《怀素师草书歌》迥异，却与写卷正面那五十九首佚名诗连贯一气。","他将两组诗相比较后，认为有两点值得注意：第一，作者身世相同，诗的内容一致；第二，有些诗句极为相仿，似出一人之手，两组诗可能为同一人所作。","他并推测这两组诗的作者，可能即为紧接前五十九首诗抄录刘商《胡笳十八拍》后又自加一拍的「落蕃人毛押牙」。","关于马云奇，柴剑虹考证其《怀素师草书歌》应作于大历六年冬至九年春之间。","并推测其可能到过河西一带，苏联藏敦煌残卷中有岑参《敦煌马太守后亭歌》，这位马太守是否马云奇，尚有待确定。","〖4〗潘重规《敦煌唐人陷蕃诗集残卷作者的新探测》〖刊一九八五年六月出版的《汉学研究》第三卷第一期〗一文，为作者在巴黎国家图书馆东方稿本部披阅敦煌原卷后写成，也认为马云奇是陷蕃诗集作者之一的说法是错误的。","潘文指出伯二五五五卷钞写诗文很多，也很杂乱。","马云奇《怀素师草书歌》后是没有作者姓名的《白云歌》等诗，前者字体较大，后者较小，并非同一人所书。","因此，不可根据前一首诗的作者，便牵连以下没有作者姓名的诗篇归属为同一人作品。","潘文进而考察了怀素的生平，考定其生于开元二十五年〖七三七〗。","马云奇诗云：「怀素才年三十余，不出湖南学草书。","」可推知此诗作于早年未出湖南时，马的年龄显然超过怀素。","敦煌陷蕃在建中二年，其时马云奇应已是六十以上的老翁。","但仔细抽绎十二首陷蕃诗及另一组五十九首作品，作者应是盛年的男儿，诗中全没有流露老翁的口吻。","因而确定《白云歌》以下十二首不可能是马云奇所作。","同时，潘文也推测七十余首陷蕃诗的作者可能是「落蕃人毛押牙〖衙〗」。","））。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f295b590-92a8-490a-a408-d1f8e6a23ac3","tags":[]},{"id":"poem-95a2e6122fc41bbf4c211ed3","title":"送崔侍御入朝","author":"李嘉祐","dynasty":"唐","verses":["十年犹执宪，万里独归春。","旧国逢芳草，青云见故人。","潘郎今发白，陶令本家贫。","相送临京口，停桡泪满巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c1ebbb06-55b7-40d1-8f23-63491faa6fa7","tags":[]},{"id":"poem-95a8d29c4dda72203af0de1a","title":"吊元鲁山 一","author":"孟郊","dynasty":"唐","verses":["[搏]鸷有余饱，鲁山长饥空。","豪人饫鲜肥，鲁山饭蒿蓬。","食名皆霸官，食力乃尧农。","君子耻新态，鲁山与古终。","天璞本平一，人巧生异同。","鲁山不自剖，全璞竟没躬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cff79683-5f8c-4939-97cd-5f98fdcd8fb6","tags":[]},{"id":"poem-95b6d141abf2cd445168f5b4","title":"题秦系山人丽句亭","author":"皎然","dynasty":"唐","verses":["独将诗教领诸生，但看青山不爱名。","满院竹声堪愈疾，乱床花片足忘情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d11823fe-453a-4fe1-a0cd-985a7a328ce9","tags":[]},{"id":"poem-95cb29d745f9e99a99194d46","title":"病马五首呈郑校书章三吴十五先辈 二","author":"曹唐","dynasty":"唐","verses":["陇上沙葱叶正齐，腾黄犹自跼羸蹄。","尾蟠夜雨红丝脆，头捽秋风白练低。","力惫未思金络脑，影寒空望锦障泥。","阶前莫怪垂双泪，不遇孙阳不敢嘶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5710a187-8b53-40fe-87be-4e5633d8712f","tags":[]},{"id":"poem-95ce14c61622fb88f001b7c9","title":"上荆南府主三让德政碑","author":"贯休","dynasty":"唐","verses":["明明赫赫中兴主，动纳诸隍冠前古。","四海英雄尽戢兵，皆如圪圪天金柱。","万姓多论政与德，请树丰碑似山岳。","一从寇灭二十年，琬琰雕镌赐重叠。","荆州化风何卓异，寡欲无为合天地。","虽立贞碑与众殊，字字皆是吾皇意。","君侯捧碑西拜泣，臣且何人恩洊及。","凤皇衔下雕龙文，德昧政虚争敢立。","函封三奏心匍匐，坚让此碑声盖国。","我恐江淹五色笔，作不立此碑之碑文不得。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0f717aea-de1d-4c03-b5b4-2e84875a269d","tags":[]},{"id":"poem-95d02726cdf90fd15fc933fe","title":"横吹曲辞 陇头水","author":"卢照邻","dynasty":"唐","verses":["陇坂高无极，征人一望乡。","关河别去水，沙塞断归肠。","马系千年树，旌悬九月霜。","从来共呜咽，皆是为勤王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f5b4927a-9a37-4e40-87ee-e75fff02d48a","tags":[]},{"id":"poem-95d4332e762596d0e871b616","title":"送田使君牧蔡州","author":"马戴","dynasty":"唐","verses":["主意思政理，牧人官不轻。","树多淮右地，山远汝南城。","望稼周田隔，登楼楚月生。","悬知蒋亭下，渚鹤伴闲行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-50ca3358-9db8-496f-8bd9-b09c8e80f758","tags":[]},{"id":"poem-95d82e1d1fdc7f3a7184ad88","title":"虚室","author":"华镇","dynasty":"宋","verses":["轩前列群山，轩后得虚室。","宛若成都居，枵然惟四壁。","清明照窗牖，不待秋月色。","万籁悄无声，终年饱岑寂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c25a2eaa-ee8e-4aa7-bf4d-7ba838cb2dd0","tags":[]},{"id":"poem-95d8a6c02352c0bbb40f3273","title":"遣兴三首 二","author":"杜甫","dynasty":"唐","verses":["高秋登塞山，南望马邑州。","降虏东击胡，壮健尽不留。","穹庐莽牢落，上有行云愁。","老弱哭道路，愿闻甲兵休。","邺中事反复，死人积如丘。","诸将已茅土，载驱谁与谋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-140c81ac-b857-408f-bf47-8938c1b2e048","tags":[]},{"id":"poem-95f6a94e9f303d5841b67cfa","title":"加颂蜀僧雪颂  其七","author":"释印肃","dynasty":"宋","verses":["浄人若信平常事，穿过髑髅连孔鼻。","多中一了一中多，城东老母难回避。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f99860ec-f11e-420e-8d78-e2f99020f43c","tags":[]},{"id":"poem-95f961dad122c60d1768072f","title":"鼓吹曲辞 芳树","author":"元稹","dynasty":"唐","verses":["芳树已寥落，孤英尤可嘉。","可怜团团叶，盖覆深深花。","游蠭竞攒刺，鬬雀亦纷拏。","天生细碎物，不爱好光华。","非无歼殄法，念尔有生涯。","春雷一声发，惊燕亦惊蛇。","清池养神蔡，已复长虾蟆。","雨露贵平施，吾其春草芽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d5eb2f6f-4806-41cf-ac0f-9764b3911007","tags":[]},{"id":"poem-9609ff938532a89ee7445409","title":"玉楼春·弄晴数点梨梢雨","author":"谢逸","dynasty":"宋","verses":["弄晴数点梨梢雨。","门外画桥寒食路。","杜鹃飞破草间烟，蛱蝶惹残花底露。","东君著意怜樊素。","一段韶华都付与。","妆成不管露桃嗔，舞罢从教风柳妒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-628","tags":[]},{"id":"poem-9612526de91eb151cefd612c","title":"古意九首 四","author":"贯休","dynasty":"唐","verses":["乾坤有清气，散入诗人脾。","圣贤遗清风，不在恶木枝。","千人万人中，一人两人知。","忆在东溪日，花开叶落时。","几拟以黄金，铸作钟子期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3ea05842-1f5c-427f-ab89-9bbac4075eb1","tags":[]},{"id":"poem-9614662af38dd9493005bebc","title":"和宋之问寒食题临江驿","author":"胡皓","dynasty":"唐","verses":["闻道山阴会，仍为火忌辰。","途中甘弃日，江上苦伤春。","流水飜催泪，寒灰更伴人。","丹心终不改，白发为谁新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0603e48a-3ed6-465a-ab42-6a89e8d198dd","tags":["寒食节","感伤"]},{"id":"poem-961646d112cbb268c37d759c","title":"移梅","author":"赵崇嶓","dynasty":"宋","verses":["邻家争乞丽春栽，玉手轻分带月培。","窗下老翁迂入骨，清斋三日为移梅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-61a2ea96-3312-4a91-aaa1-e6dda38e168d","tags":[]},{"id":"poem-9620075e4fd0dcb784153142","title":"赠宿将","author":"李山甫","dynasty":"唐","verses":["校猎燕山经几春，雕弓白羽不离身。","年来马上浑无力，望见飞鸿指似人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-804ac476-3c58-4164-aaca-30549dd0970e","tags":[]},{"id":"poem-96207f8b5ac5c6f5ba050d9c","title":"维扬万花园","author":"宋伯仁","dynasty":"宋","verses":["细柳营基锁绿苔，万花新种小亭台。","芙蓉喜见江南客，故向西风一夜开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d80dba85-b17f-44b0-8781-8e44b1a7eb73","tags":[]},{"id":"poem-96209cceebb3bcc96bb1ae76","title":"奉和圣制荅张说扈从南出雀鼠谷","author":"赵冬曦","dynasty":"唐","verses":["轩辕应顺动，力牧正趋陪。","道合殷为砺，时行楚有材。","省方西礼设，振旅北京回。","地理分中壤，天文照上台。","寒依汾谷去，春入晋郊来。","窃比康衢者，长歌仰大哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fd656857-3054-4245-a998-e7daa58fc6e5","tags":[]},{"id":"poem-96291b4d4bb4a6afef1fca4e","title":"和常州崔使君咏后庭梅二首 一","author":"孙逖","dynasty":"唐","verses":["闻唱梅花落，江南春意深。","更传千里外，来入越人吟。","弱干红妆倚，繁香翠羽寻。","庭中自公日，歌舞向芳阴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8665cd4a-9bc7-40d8-8ea5-8ac3b866d15c","tags":[]},{"id":"poem-9629f39b9a4726c2da427dab","title":"诉衷情·烛尽香残帘半卷","author":"韦庄","dynasty":"五代","verses":["烛尽香残帘半卷，梦初惊。","花欲谢，深夜，月胧明。","何处按歌声，轻轻。","舞衣尘暗生，负春情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-16","tags":[]},{"id":"poem-962b7efa24ddddf46affb881","title":"黍苗","author":"佚名","dynasty":"先秦","verses":["芃芃黍苗，阴雨膏之。悠悠南行，召伯劳之。","我任我辇，我车我牛。我行既集，盖云归哉。","我徒我御，我师我旅。我行既集，盖云归处。","肃肃谢功，召伯营之。烈烈征师，召伯成之。","原隰既平，泉流既清。召伯有成，王心则宁。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-226","tags":[]},{"id":"poem-962e089976cdf7c024785dca","title":"鸱鸮","author":"佚名","dynasty":"先秦","verses":["鸱鸮鸱鸮，既取我子，无毁我室。恩斯勤斯，鬻子之闵斯。","迨天之未阴雨，彻彼桑土，绸缪牖户。今女下民，或敢侮予？","予手拮据，予所捋荼。予所蓄租，予口卒瘏，曰予未有室家。","予羽谯谯，予尾翛翛，予室翘翘。风雨所漂摇，予维音哓哓！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-154","tags":[]},{"id":"poem-96376f51e534cb548bf9af78","title":"朝中措·蜀弦秦柱不关情","author":"纳兰性德","dynasty":"清","verses":["蜀弦秦柱不关情，尽日掩云屏。","己惜轻翎退粉，更嫌弱絮为萍。","东风多事，余寒吹散，烘暖微酲。","看尽一帘红雨，为谁亲系花铃。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-73","tags":[]},{"id":"poem-963d0d852b3f0ea825b68b54","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(末)谁是谁非，请不须再三提起，提将起恐伊羞耻。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1701","tags":[]},{"id":"poem-964c4ea379aef53f1dc69609","title":"郊庙歌辞 享太庙乐章 大明舞","author":"魏征、褚亮","dynasty":"唐","verses":["五纪更运，三正递升。","勋华既没，禹汤勃兴。","神武命代，灵睠是膺。","望云彰德，察纬告征。","上纽天维，下安地轴。","征师涿野，万国咸服。","偃伯灵台，九官允穆。","殊域委賮，怀生介福。","大礼既饰，大乐已和。","黑章扰囿，赤字浮河。","功宣载籍，德被咏歌。","克昌厥后，百禄是荷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-dc517fb4-afe5-4836-82dd-4b05d9a66851","tags":[]},{"id":"poem-965043d386958df4a73a9f39","title":"柳枝·风情渐老见春羞","author":"李煜","dynasty":"五代","verses":["风情渐老见春羞，到处芳魂感旧游。","多谢长条似旧识，强垂烟穗拂人头。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-39","tags":[]},{"id":"poem-965a8e0a9ecbe073cfef6437","title":"尊师是桃源黄先生传法弟子常见尊师称先师灵迹今重赋此诗兼寄题黄先生旧馆","author":"李德裕","dynasty":"唐","verses":["后学方成市，吾师又上宾。","洞天应不夜，源树秪如春。","棋客留童子，山精避直神。","无因握石髓，及与养生人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e283ac05-0ee6-4342-b972-af263c1e2405","tags":[]},{"id":"poem-967295b0e8bca637237bd653","title":"蝶恋花·九里山前千里路","author":"陈师道","dynasty":"宋","verses":["九里山前千里路。","流水无情，只送行人去。","路转河回寒日暮。","连峰不许重回顾。","水解随人花却住。","衾冷香销，但有残妆污。","泪入长江空几许。","双洪一抹无寻处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-330","tags":["长江"]},{"id":"poem-9683d9c7b2bbf388105f8e99","title":"过马嵬二首 一","author":"李益","dynasty":"唐","verses":["路至墙垣问樵者，顾予云是太真宫。","太真血染马蹄尽，朱阁影随天际空。","丹壑不闻歌吹夜，玉堦唯有薜萝风。","世人莫重霓裳曲，曾致干戈是此中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9657c24a-5dc0-409d-af80-ab182a7d336f","tags":[]},{"id":"poem-9684b49a445412467790ea16","title":"泗水行","author":"张籍","dynasty":"唐","verses":["泗水流急石纂纂，鲤鱼上下红尾短。","春冰销散日华满，行舟往来浮桥断。","城边鱼市人早行，水烟漠漠多棹声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4453d037-74ce-434d-8db0-1c63b6cc62b8","tags":[]},{"id":"poem-9687403ffdeba9083181524e","title":"送刘评事充朔方判官赋得征马嘶","author":"高适","dynasty":"唐","verses":["征马向边州，萧萧嘶不休。","思深应带别，声断为兼秋。","岐路风将远，关山月共愁。","赠君从此去，何日大刀头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b42b8d7b-3d04-46ed-ba87-11478e25d391","tags":[]},{"id":"poem-96a3b590cd4827230dcc4757","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["来的是甚人？闷中无由，一声询问。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5275","tags":[]},{"id":"poem-96a6e5f98a23ffacbd737c16","title":"和仰庵池上梅韵","author":"王柏","dynasty":"宋","verses":["窗外梅兄不可无，山人一见两眉舒。","江头千树应难得，池上数根宜有余。","蟾魄浮香无定相，虬枝压水可常居。","只愁疎影翻多事，一片清光不得虚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-522eaf70-1e15-4b20-9b32-9d866bc027f5","tags":[]},{"id":"poem-96ab7abe73af7b6c6fdd3f8b","title":"偈颂三十首  其一","author":"释印肃","dynasty":"宋","verses":["捏不成团拨不开，何须南岳又天台。","六根门首无人用，惹得胡僧特地来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-58bd5e35-186b-43c5-aca2-4f6d626ea93c","tags":[]},{"id":"poem-96b13347708684a096ae2987","title":"题陈主管东墙三岘图","author":"陈造","dynasty":"宋","verses":["堂上不合青枫起烟雾，墙间江山更疑误。","千岩万壑眩明灭，暖翠浮岚满窗户。","岘山鼎列屹相望，发地撑空𬸣欲翔。","一峰拔起群山上，嶪若紫盖相雄长。","仙山佛国住杳霭，晨烟暮云追戃恍。","良工妙与山写真，诗中有画须诗人。","诵君清诗对画壁，承蜩斲鼻俱疑神。","知君怀古有高趣，我擥襄山识佳处。","愿抄此诗誊此图，开卷时时揖羊杜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a9fc076e-35d3-4106-a9f3-41abefb8d0f7","tags":[]},{"id":"poem-96b4e11c26ee2a745b080e75","title":"满江红·击碎空明","author":"高观国","dynasty":"宋","verses":["击碎空明，沧浪晚、棹歌飞入。","西山外、紫霞吹断，赤尘无迹。","飞上冰轮凉世界，唤回天籁清肌骨。","看骊珠、影堕冷光斜，蛟龙窟。","长啸外，纶巾侧。","轻露下，纤𫄨湿。","听洞箫声在，卧虹阴北。","十万江妃留醉梦，二三沙鸟惊吟魄。","任天河、落尽玉杯空，东方白。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-407","tags":[]},{"id":"poem-96d05924e9d08ad91a2e967f","title":"兵后寻边三首 二","author":"李山甫","dynasty":"唐","verses":["旗头指处见黄埃，万马横驰鹘翅回。","劒戟远腥凝血在，山河先暗阵云来。","角声恶杀悲于哭，鼓势争强怒若雷。","日暮却登寒垒望，饱鸱清啸伏尸堆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-cf73cabf-0d1b-4231-b0b4-ab22e1c96135","tags":[]},{"id":"poem-96d4ee9ab39bcdf7006e4b2b","title":"腊月二十二日渡湘登道乡台夜归得五绝  其三","author":"张栻","dynasty":"宋","verses":["道旁老松高拂云，刳心取明彼何人。","说与往来须爱护，雪霜时节看长身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-7ce9d179-f9d5-403b-95b9-c24685d92473","tags":[]},{"id":"poem-96da6e784bbcc1d67b94683e","title":"寻徐道士","author":"张籍","dynasty":"唐","verses":["寻师远到晖天观，竹院森森闭药房。","闻入静来经七日，仙童簷下独焚香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cfc14bee-9fa0-4706-b0fc-380d3562d90b","tags":[]},{"id":"poem-96ea1f2379821935e5059ec4","title":"阅田禾","author":"吕从庆","dynasty":"唐","verses":["村南村北稻花明，碧影清光夹望平。","节弄暑风轻拂拂，尖悬晚露澹盈盈。","道傍妪妇呼鸡返，坡外儿童跨犊行。","独坐小桥幽兴满，蟪蛄声在柳梢鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-95be15f7-5e76-4eeb-bcc5-2754b6e0d55a","tags":[]},{"id":"poem-96f80b3cf3eb9786098dc16b","title":"保真院","author":"陈岩","dynasty":"宋","verses":["野寺荒山涧水滨，古藤翠筿自摇春。","僧闲晏坐无人到，内保禅心一味真。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5b07251d-787d-4c6f-a98e-fb26d4e9699d","tags":[]},{"id":"poem-96f81ed0152b48e34895af23","title":"岁除夜有怀","author":"孟浩然","dynasty":"唐","verses":["迢递三巴路，羁危万里身。","乱山残雪夜，孤灯异乡人。","渐与骨肉远，转于奴仆亲。","那堪正飘泊，来日岁华新。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0f5af383-765a-4d56-b00b-79ee2ccd5111","tags":["唐诗三百首","羁旅","五言律诗","春节","思乡"]},{"id":"poem-96f8d9245b07060c4a94724b","title":"句  其一","author":"王溥","dynasty":"宋","verses":["两制职官三十客，自怜荣耀老莱衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-127de090-3507-48d6-abbf-3747b4e09684","tags":[]},{"id":"poem-9702da0a93f12a64575bf87f","title":"浣溪沙·帐饮都门春浪惊","author":"晁补之","dynasty":"宋","verses":["帐饮都门春浪惊。","东飞身与白鸥轻。","淮山一点眼初明。","谁使梦回兰芷国，却将春去凤凰城。","樯乌风转不胜情。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-205","tags":[]},{"id":"poem-9721e5d8077051adc12a61cb","title":"巡省途次上党旧宫赋","author":"明皇帝","dynasty":"唐","verses":["三千初击浪，九万欲抟空。","天地犹惊否，阴阳始遇蒙。","存贞期历试，佐贰伫昭融。","多谢时康理，良慙实赖功。","长怀问鼎气，夙负拔山雄。","不学刘琨舞，先歌汉祖风。","英髦既包括，豪杰自牢笼。","人事一朝异，讴歌四海同。","如何昔朱邸，今此作离宫？","雁沼澄澜翠，猿岩落照红。","小山秋桂馥，长坂旧兰丛。","即是淹留处，乘欢乐未穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e3e09dbc-9565-4d64-a1e3-92f22726430f","tags":[]},{"id":"poem-9731413cd696c6e8f659a2bb","title":"冬夕会诸同僚与税舍弟郡斋饮话通判欧郎中以二绝句纪事见寄次韵  其一","author":"苏颂","dynasty":"宋","verses":["弟兄叨郡两淮间，宾友衔杯午夜欢。","喜听话言消酒力，更钦风义敌霜寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d3358aa7-f2f4-494d-86a3-8354e9d6680b","tags":[]},{"id":"poem-9740d8e9f28a03d50cd72bb2","title":"明堂观礼杂咏十三首 和宁门观驾","author":"王同祖","dynasty":"宋","verses":["星斗中天夜向晨，寸云不点月华明。","六飞过尽灯如昼，宫漏迟迟报五更。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-32c2caa6-5c43-4ba1-8d16-1b092b26a1c6","tags":[]},{"id":"poem-974a1a87f32263c14849868e","title":"和中书侍郎院壁画云","author":"李收","dynasty":"唐","verses":["粉壁画云成，如能上太清。","影从霄汉发，光照掖垣明。","暎筿多幽趣，临轩得野情。","独思作霖雨，流润及生灵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5eb98284-b6e8-4232-acf1-47cc896293d1","tags":[]},{"id":"poem-974abc0b2f63794cd76363a4","title":"剔银灯·何事春工用意","author":"柳永","dynasty":"宋","verses":["何事春工用意。","绣画出、万红千翠。","艳杏夭桃，垂杨芳草，各斗雨膏烟腻。","如斯佳致。","早晚是、读书天气。","渐渐园林明媚。","便好安排欢计。","论槛买花，盈车载酒，百琲千金邀妓。","何妨沈醉。","有人伴、日高春睡。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-207","tags":[]},{"id":"poem-97558ef4218d4c40837a0da2","title":"细言","author":"雍裕之","dynasty":"唐","verses":["蚊眉自可托，蜗角岂劳争。","欲効丝毫力，谁知蝼蚁诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e1b6cceb-d0d9-47f7-a69d-823dff274f69","tags":[]},{"id":"poem-975faaa84593c21c171d500a","title":"拜明招二先生墓有感  其五","author":"王柏","dynasty":"宋","verses":["炯炯长空一片心，东南鼎立统斯文。","卷藏万古春归去，只有余光在此君。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a6d55c21-ca44-43ef-b894-875bbd649e5c","tags":[]},{"id":"poem-97722348d02f03ddf66d3636","title":"菩萨蛮·风帘燕舞莺啼柳","author":"牛峤","dynasty":"五代","verses":["风帘燕舞莺啼柳，妆台约鬓低纤手。","钗重髻盘珊，一枝红牡丹。","门前行乐客，白马嘶春色。","故故坠金鞭，回头应眼穿。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-18","tags":[]},{"id":"poem-979085d074bbb3aa9b04994d","title":"寄漫塘刘平国索竹岩钱德载挽章","author":"释居简","dynasty":"宋","verses":["一从神武挂衣冠，千载华风去不还。","闲惬清宁羞宦巧，静闚奔竞识天悭。","高于少室从它售，捷似终南各自扳。","我欲西风问无恙，不知著得几鸥闲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a54f8467-9168-4ca6-ac1e-7a228f9ebc08","tags":[]},{"id":"poem-979503b45f7fe6c4c4bf130a","title":"次韵许深父  其一","author":"张栻","dynasty":"宋","verses":["日日经行只小园，静搘邛竹听鸣泉。","此时心事何人共，素壁题诗第几篇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-88dee025-c152-42cb-88c0-5de8fc3e26b4","tags":[]},{"id":"poem-9796d0c2b00fddaed5552ccc","title":"池上","author":"释居简","dynasty":"宋","verses":["冰澌潄齿夜生寒，白苎生裁踏月残。","水面有风人不见，只教荷气上阑干。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-072af8ae-74f4-41f0-a75c-4b1a43e6cc0e","tags":[]},{"id":"poem-97986e6b429ee36273aa09ef","title":"我将","author":"佚名","dynasty":"先秦","verses":["我将我享，维羊维牛，维天其右之。仪式刑文王之典，日靖四方。","伊嘏文王，既右飨之。我其夙夜，畏天之威，于时保之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-271","tags":[]},{"id":"poem-97a2384cccec8522b636ca61","title":"朝中措·斜斜整整暗江湾","author":"曹勋","dynasty":"宋","verses":["斜斜整整暗江湾。","蓑笠有无间。","应与君家却暑，冷看白满群山。","想来何处，金炉焰兽，玉斝酡颜。","好是溪涵寒影，山影一棹人还。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-158","tags":[]},{"id":"poem-97acfaee32b12034593b63bf","title":"发刘郎浦","author":"杜甫","dynasty":"唐","verses":["挂帆早发刘郎浦，疾风飒飒昏亭午。","舟中无日不沙尘，岸上空村尽豺虎。","十日北风风未回，客行岁晚晚相催。","白头厌伴渔人宿，黄帽青鞋归去来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-83fab156-6339-4b67-aca1-5ee2b16f2680","tags":[]},{"id":"poem-97add0df09c056d959b34062","title":"残莺百啭歌同王员外耿拾遗吉中孚李端游慈恩各赋一物","author":"司空曙","dynasty":"唐","verses":["残莺一何怨，百啭相寻续。","始辨下将高，稍分长复促。","绵蛮巧状语，机节终如曲。","野客赏应迟，幽僧闻讵足。","禅斋深树夏阴清，零落空余三两声。","金谷筝中传不似，山阳笛里写难成。","忆昨乱啼无远近，晴宫晓色偏相引。","送暖初随柳色来，辞芳暗逐花枝尽。","歌残莺，歌残莺，悠然万感生。","谢朓羇怀方一听，何郎闲吟本多情。","乃知众鸟非俦比，暮噪晨鸣倦人耳。","共爱奇音那可亲，年年出谷待新春。","此时断绝为君惜，明日玄蝉催发白。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b47d819e-df0d-47a8-8864-5aadeb8190f8","tags":[]},{"id":"poem-97b8cd0c3b375ecb44a9e443","title":"宿广德寺寄从舅","author":"张籍","dynasty":"唐","verses":["古寺客堂空，开帘四面风。","移床动栖鹤，停烛聚飞虫。","闲卧逐凉处，远愁生静中。","林西微月色，思与宁家同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6781ec4f-db7c-4fba-9ee0-ec6fa445733e","tags":[]},{"id":"poem-97c3cf7b675278eb7da58ca8","title":"蝶恋花·闻说君家传窈窕","author":"毛滂","dynasty":"宋","verses":["闻说君家传窈窕。","秀色天真，更夺丹青妙。","细意端相都总好。","春愁春媚生颦笑。","琼玉胸前金凤小。","那得殷勤，细托琵琶道。","十二峰云遮醉倒。","华灯翠帐花相照。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-811","tags":[]},{"id":"poem-97cdc06326cc46ab6ccbe374","title":"咏屏风","author":"袁恕己","dynasty":"唐","verses":["绮阁云霞满，芳林草树新。","鸟惊疑欲曙，花笑不关春。","山对弹琴客，谿留垂钓人。","请看车马客，行处有风尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e31997de-b936-45db-9463-20c0e1a44693","tags":[]},{"id":"poem-97cf38258065dc78a4760a81","title":"律僧","author":"张籍","dynasty":"唐","verses":["苦行长不出，清羸最少年。","持斋唯一食，讲律岂曾眠。","避草每移径，滤虫还入泉。","从来天竺法，到此几人传。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5e511964-25aa-42b4-8e37-c92c84246060","tags":[]},{"id":"poem-97d905db306591eeeefa0347","title":"次韵和丹阳裴如晦学士寄示与蔡子直陈述古唱酬五篇  其三","author":"苏颂","dynasty":"宋","verses":["𬘘鼓吴门彻曙开，郡人还喜邓侯来。","政成岁稔庭无讼，谁伴南园举宴杯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b0c117b9-1ae2-48fc-9060-81a1ecc15c9e","tags":[]},{"id":"poem-97ef0c1d9804ef994999107e","title":"减字木兰花·花丛冷眼","author":"纳兰性德","dynasty":"清","verses":["花丛冷眼，自惜寻春来较晚。","知道今生，知道今生那见卿。","天然绝代，不信相思浑不解。","若解相思，定与韩凭共一枝。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-83","tags":[]},{"id":"poem-97f818e6c876e6a455b2686b","title":"木兰花・玉楼春·银黄雁柱香檀拨","author":"贺铸","dynasty":"宋","verses":["银黄雁柱香檀拨。","镂板三声催细抹。","舞腰轻怯绛裙长，羞按筑球花十八。","东城柳岸匆匆发。","画舫一篙烟水阔。","可怜单枕欲眠时，还见尊前前夜月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-857","tags":[]},{"id":"poem-97ffd91504b95d073b96ab78","title":"代故人新姬侍疾","author":"王建","dynasty":"唐","verses":["双毂不回辙，子疾已在傍。","侍坐长摇扇，迎医渐下床。","新施箱中幔，未洗来时妆。","奉君缠绵意，幸愿莫相忘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1d84e98a-9ad7-4e40-b772-4da9680ad763","tags":[]},{"id":"poem-980c8d9d8feb18b022ea8055","title":"用安之韵招君从安之正叔不疑二十六日南园为真率会  其二","author":"司马光","dynasty":"宋","verses":["真率春来频宴聚，不过东里即西家。","小园容易邀嘉客，馔具虽无亦有花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-03f92636-c6cb-426d-b180-084338e97148","tags":[]}];
